#[cfg(test)]
mod background_behavior_model_admission_source_oracles {
    /// A behavior-bound model turn is admitted for one reviewed step or not at
    /// all.
    ///
    /// This oracle used to assert the opposite mechanism — that scheduled
    /// behaviors were refused BEFORE live binding resolution — because no
    /// recipe contract existed and an allow-set could not be executed without
    /// guessing. Now one does, so admission legitimately happens after the
    /// manifest is open. What must not change is that the step is admitted
    /// from reviewed material, and that the live recipe is re-verified against
    /// the grant before any of it is believed.
    #[test]
    fn behavior_model_admission_binds_one_reviewed_step() {
        let source = include_str!("workflows.rs");
        let boundary = source
            .split(concat!(
                "    fn model_input_from_state<'a>(",
                "\n",
                "        &'a self,"
            ))
            .nth(1)
            .expect("model-input boundary must remain present");
        let admission = boundary
            .find("self.admit_recipe_step(")
            .expect("a behavior-bound turn must be admitted for an exact reviewed step");
        let construction = boundary
            .find("Ok(AppWorkflowModelInput {")
            .expect("model input construction must remain present");
        assert!(
            admission < construction,
            "the step must be admitted before the model input is built"
        );

        // `concat!` so this oracle's own source does not contain the joined
        // anchor. A self-matching split silently windows the TEST text instead
        // of the function, and every assertion below is then satisfied by its
        // own literal — the oracle passes while pinning nothing.
        let admit = source
            .split(concat!("    fn admit_recipe_step(", "\n", "        &self,"))
            .nth(1)
            .and_then(|tail| {
                tail.split(concat!(
                    "    fn model_input_from_state<'a>(",
                    "\n",
                    "        &'a self,"
                ))
                .next()
            })
            .expect("recipe admission must remain present");
        // The grant was reviewed against a specific recipe. A package update
        // that reorders steps or drops a guard must not ride the old grant.
        assert!(admit.contains("app_behavior_steps_digest"));
        assert!(admit.contains("live_digest != granted_steps_digest"));
        // An allow-set with no recipe is still refused: that refusal is the
        // whole reason the dispatcher was unreachable.
        assert!(admit.contains("BackgroundBehaviorOperationStepBindingRequired"));
        // A finished recipe is not an OPERATION turn — it carries no step, so
        // the dispatch fork cannot take it — but it is still an admissible
        // input. Making it an error refused the tool disclosures, store
        // queries and terminal commit the behavior's own workflow turn still
        // owed after its recipe ran.
        assert!(admit.contains("Ok(AppRecipeAdmission::Complete)"));
        assert!(!admit.contains("Err(AppWorkflowError::BackgroundBehaviorRecipeComplete)"));
        // `Complete` is settled only after the live recipe re-derives the
        // grant's digest, so a stale package cannot reach it either.
        let digest_check = admit
            .find("live_digest != granted_steps_digest")
            .expect("the grant digest check must remain present");
        let complete = admit
            .find("Ok(AppRecipeAdmission::Complete)")
            .expect("the complete arm must remain present");
        assert!(digest_check < complete);
        // The per-run token ceiling is derived from DURABLE progress here, not
        // counted in the dispatching frame. A frame counter is re-seeded to the
        // full grant by every continuation of the same run, which silently
        // turns the reviewed per-run ceiling into a per-continuation one.
        let run = admit
            .split("AppBehaviorRecipeNext::Run(step) =>")
            .nth(1)
            .expect("the run arm must remain present");
        let derived = run
            .find("remaining_run_output_tokens(")
            .expect("the remaining budget must be derived from durable progress");
        let construction = run
            .find("AppRecipeAdmission::Step(Box::new(AppAdmittedRecipeStep {")
            .expect("admitted step construction must remain present");
        assert!(derived < construction);
        assert!(run[..construction].contains("state.behavior_recipe_progress"));
        // A run with nothing left refuses instead of being handed a step.
        assert!(run[..construction].contains("BackgroundBehaviorRunTokensExhausted"));
    }

    /// A recipe step's reviewed output reaches the turn that must act on it.
    ///
    /// Recording the output durably is only half the loop. The other half is
    /// that the model input the workflow's own turn is rendered from carries
    /// that record — otherwise a recipe whose terminal step composes a value
    /// pays for a permit-gated `app:` turn, schema-validates the result,
    /// writes it, and then hands the workflow a prompt that has never seen it,
    /// forcing the workflow to recompose what was already bought.
    #[test]
    fn recorded_recipe_outputs_reach_the_model_input() {
        let source = include_str!("workflows.rs");
        let boundary = source
            .split(concat!(
                "    fn model_input_from_state<'a>(",
                "\n",
                "        &'a self,"
            ))
            .nth(1)
            .and_then(|tail| tail.split("    fn resolve_workflow_personality(").next())
            .expect("model-input boundary must remain present");
        // The durable progress record itself, not a summary derived from it:
        // the outputs were validated against the steps' reviewed schemas
        // before they were stored, and re-deriving them here would be a second
        // interpretation of authority.
        assert!(boundary.contains("recipe_progress: state.behavior_recipe_progress.clone()"));

        let recorded = source
            .split(concat!(
                "    pub async fn record_recipe_step_output(",
                "\n",
                "        &self,"
            ))
            .nth(1)
            .and_then(|tail| {
                tail.split("    pub(crate) async fn record_agent_tool_model_admission(")
                    .next()
            })
            .expect("recipe step recording must remain present");
        // Validation still gates the write, so nothing unvalidated can enter
        // the progress the prompt is rendered from.
        assert!(recorded.contains("output_schema()"));
        assert!(recorded.contains("BackgroundBehaviorStepOutputRejected"));
        // A recipe that owes nothing has no step to record against.
        assert!(recorded.contains("AppRecipeAdmission::Complete =>"));
    }
}

/// Keep the shipped native round, its reviewed semantic step and its drafting
/// prompt in agreement. Mechanical eligibility and writes belong to the host;
/// the model sees the recipe's context and returns the declared draft envelope.
#[cfg(test)]
mod town_square_ambient_turn_wiring {
    use crate::magician_v2::apps::manifest::{
        parse_app_manifest_frontmatter, AppPackageLimits, CanonicalAppManifest,
    };

    const AMBIENT_TURN_PROMPT: &str = "workflows/take-ambient-turn.md";

    fn package_file(relative: &str) -> String {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../magician_data_v3/system/town_square/app")
            .join(relative);
        std::fs::read_to_string(&path)
            .unwrap_or_else(|error| panic!("shipped town square file `{relative}`: {error}"))
    }

    /// Lowercased with every whitespace run collapsed to one space, so a
    /// phrase assertion cannot be defeated — or falsely satisfied — by where a
    /// prose file happens to wrap.
    fn collapsed(text: &str) -> String {
        text.split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .to_lowercase()
    }

    fn shipped_manifest() -> CanonicalAppManifest {
        parse_app_manifest_frontmatter(
            package_file("SKILL.md").as_bytes(),
            &AppPackageLimits::for_bounded_yaml(256 * 1024),
        )
        .expect("shipped town square manifest parses")
    }

    fn round_node() -> serde_json::Value {
        let manifest = shipped_manifest();
        let app = &manifest.manifest().app;
        let behavior = &app.behaviors[0];
        let workflow = &app.workflows[&app.actions[&behavior.action].workflow];
        assert_eq!(
            workflow.runner,
            crate::magician_v2::apps::manifest::AppManifestRunner::Recipe
        );
        assert_eq!(workflow.prompt.as_str(), AMBIENT_TURN_PROMPT);
        let recipe: serde_json::Value = serde_json::from_str(&package_file(
            workflow
                .recipe
                .as_ref()
                .expect("native recipe member")
                .as_str(),
        ))
        .unwrap();
        let root = recipe["recipe"]["root"].as_str().unwrap();
        recipe["recipe"]["nodes"][root]["node"].clone()
    }

    #[test]
    fn the_native_round_binds_the_one_reviewed_semantic_step() {
        let manifest = shipped_manifest();
        let behavior = &manifest.manifest().app.behaviors[0];
        let node = round_node();
        assert_eq!(node["kind"], "contextual_round");
        assert_eq!(behavior.steps.len(), 1);
        let step = &behavior.steps[0];
        assert_eq!(node["program"]["semantic_step"], step.id.as_str());
        assert_eq!(step.operation.as_str(), "compose_post");
        assert!(step.when.is_none());
        assert_eq!(node["program"]["max_output_tokens"], 1600);
    }

    #[test]
    fn the_behaviors_action_may_write_the_rows_its_recipe_mutates() {
        let manifest = shipped_manifest();
        let app = &manifest.manifest().app;
        let workflow = &app.workflows[&app.actions[&app.behaviors[0].action].workflow];
        let node = round_node();
        let program = &node["program"];
        for mutation in program["mutations"]
            .as_array()
            .unwrap()
            .iter()
            .chain(program["final_mutations"].as_array().unwrap())
        {
            assert!(
                workflow
                    .may_mutate
                    .iter()
                    .any(|entity| { Some(entity.as_str()) == mutation["entity"].as_str() }),
                "every native mutation needs the workflow's write authority"
            );
        }
    }

    #[test]
    fn the_prompt_drafts_without_dispatching_operations_or_mutations() {
        let prompt = collapsed(&package_file(AMBIENT_TURN_PROMPT));
        for forbidden in [
            "call `engagement_gate`",
            "call `compose_post`",
            "call the `compose_post`",
        ] {
            assert!(!prompt.contains(forbidden));
        }
        assert!(prompt.contains("you have no tools"));
        assert!(prompt.contains("you draft only"));
        assert!(prompt.contains("do not output mutation commands"));
        for field in [
            "outcome",
            "reason",
            "body",
            "post_type",
            "target_post_id",
            "mentioned_member_ids",
        ] {
            assert!(
                prompt.contains(&format!("`{field}`")),
                "draft contract: {field}"
            );
        }
    }

    #[test]
    fn the_prompt_reads_context_from_the_native_round_queries() {
        let prompt = package_file(AMBIENT_TURN_PROMPT);
        assert!(prompt.contains("`context`"));
        let node = round_node();
        let queries = node["program"]["queries"].as_array().unwrap();
        for name in [
            "member",
            "mood",
            "feed",
            "members",
            "mentions",
            "own_recent",
            "policy",
        ] {
            assert!(queries.iter().any(|query| query["name"] == name));
            assert!(
                prompt.contains(&format!("`{name}`")),
                "context contract: {name}"
            );
        }
        let renderer = include_str!("workflow_model_context.rs");
        assert!(renderer.contains("\"context\""));
    }

    #[test]
    fn the_host_recipe_owns_eligibility_before_model_dispatch() {
        let node = round_node();
        let eligibility = node["program"]["eligibility"].as_array().unwrap();
        for reason in [
            "autonomy_off",
            "member_not_enrolled",
            "member_opted_out",
            "cooldown",
            "agent_busy",
        ] {
            assert!(eligibility.iter().any(|guard| guard["reason"] == reason));
        }
        let source = collapsed(&package_file("SKILL.md"));
        assert!(source.contains(
            "missing policy or `autonomy_state: off` excludes candidates before model dispatch"
        ));
        assert!(package_file(AMBIENT_TURN_PROMPT).contains("policy[0].fields.max_post_chars"));
    }

    #[test]
    fn the_reviewed_model_route_and_source_handling_are_written_down() {
        let manifest = shipped_manifest();
        assert_eq!(
            manifest
                .manifest()
                .app
                .data_policy
                .defaults
                .model_processing,
            crate::magician_v2::apps::models::AppModelProcessing::RemoteAllowed
        );
        let source = package_file("SKILL.md");
        for required in [
            "app_platform.llm_operations.compose_post",
            "app:compose_post",
            "op-app-workflow-remote",
            "op-app-workflow-local",
            "more restrictive source",
        ] {
            assert!(source.contains(required), "operator contract: {required}");
        }
    }
}

#[derive(Debug)]
pub(crate) enum AppRecipeCanonicalNodeAdmission {
    Dispatch(AppRecipeCanonicalNodePermit),
    ResumeIdenticalRead(AppRecipeCanonicalNodePermit),
    AlreadySettled,
    OwnedByLiveWorker,
    Cancelled,
    OutcomeUncertain,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum AppRecipeCanonicalRunDisposition {
    Active,
    CancellationRequested,
    OutcomeUncertain,
}

/// In-memory, non-serializable evidence for mirroring a cancellation request
/// after the canonical V3 schedule accepted it under the task write lock.
pub(crate) struct AppRecipePreparedCancellation {
    run: AppRecipeControlRun,
    request_digest: AppDigest,
    requested_at_ms: i64,
}

/// Move-only proof that the exact V3 schedule step reached `started` before
/// its owner can perform work. Only the Artifact service constructs it and the
/// same service must consume it when the typed output becomes canonical.
#[derive(Debug)]
pub(crate) struct AppRecipeCanonicalNodePermit {
    step_id: String,
    binding_digest: AppDigest,
    input_digest: AppDigest,
    attempt: u16,
    claim_owner_id: String,
    claim_epoch: u64,
    deadline_at_ms: i64,
    heartbeat_stop: Option<tokio::sync::oneshot::Sender<()>>,
    heartbeat_outcome: Option<tokio::sync::oneshot::Receiver<AppRecipeCanonicalRunDisposition>>,
}

impl AppRecipeCanonicalNodePermit {
    pub(crate) fn from_v3_started(
        step_id: String,
        binding_digest: AppDigest,
        input_digest: AppDigest,
        attempt: u16,
        claim_owner_id: String,
        claim_epoch: u64,
        deadline_at_ms: i64,
        heartbeat_stop: tokio::sync::oneshot::Sender<()>,
        heartbeat_outcome: tokio::sync::oneshot::Receiver<AppRecipeCanonicalRunDisposition>,
    ) -> Result<Self, AppWorkflowError> {
        if step_id.is_empty()
            || attempt == 0
            || claim_owner_id.is_empty()
            || claim_epoch == 0
            || deadline_at_ms <= 0
        {
            return Err(AppWorkflowError::CorruptBinding);
        }
        Ok(Self {
            step_id,
            binding_digest,
            input_digest,
            attempt,
            claim_owner_id,
            claim_epoch,
            deadline_at_ms,
            heartbeat_stop: Some(heartbeat_stop),
            heartbeat_outcome: Some(heartbeat_outcome),
        })
    }

    pub(crate) fn step_id(&self) -> &str {
        &self.step_id
    }

    pub(crate) fn binding_digest(&self) -> &AppDigest {
        &self.binding_digest
    }

    pub(crate) fn input_digest(&self) -> &AppDigest {
        &self.input_digest
    }

    pub(crate) fn attempt(&self) -> u16 {
        self.attempt
    }

    pub(crate) fn claim_owner_id(&self) -> &str {
        &self.claim_owner_id
    }

    pub(crate) fn claim_epoch(&self) -> u64 {
        self.claim_epoch
    }

    pub(crate) fn deadline_at_ms(&self) -> i64 {
        self.deadline_at_ms
    }

    pub(crate) fn stop_heartbeat(&mut self) {
        if let Some(stop) = self.heartbeat_stop.take() {
            let _ = stop.send(());
        }
    }

    pub(crate) fn take_heartbeat_outcome(
        &mut self,
    ) -> Result<tokio::sync::oneshot::Receiver<AppRecipeCanonicalRunDisposition>, AppWorkflowError>
    {
        self.heartbeat_outcome
            .take()
            .ok_or(AppWorkflowError::CorruptBinding)
    }
}

/// Narrow bridge to the canonical Artifact V3 execution/reducer owner. The
/// recipe lifecycle store may seal intent and output evidence, but callers
/// must consult this owner for every node start and terminal transition.
#[async_trait::async_trait]
pub(crate) trait AppRecipeCanonicalNodeOwner: Send + Sync {
    async fn dispatch_recipe_semantic(
        &self,
        _scope: &ScopeRef,
        _task_id: &str,
        _run: &AppRecipeAttachedRun,
        _node_id: &AppName,
        _permit: &AppRecipeCanonicalNodePermit,
        _input: AppNativeSemanticInput,
    ) -> Result<super::llm_dispatch::AppLlmDispatchResult, AppWorkflowError> {
        _input.mark_dispatch_completed();
        Err(AppWorkflowError::ProcessingContextUnavailable)
    }

    async fn recipe_builtin_provider(
        &self,
        _scope: &ScopeRef,
        _tool: &str,
    ) -> Result<
        crate::magician_v2::execution::capability::AppBuiltinProviderWitness,
        AppWorkflowError,
    > {
        Err(AppWorkflowError::RecipeBindingUnavailable)
    }

    async fn prepare_recipe_schedule(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
    ) -> Result<(), AppWorkflowError>;

    async fn begin_recipe_node(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        node_id: &AppName,
        input: &AppValidatedWorkflowValue,
    ) -> Result<AppRecipeCanonicalNodeAdmission, AppWorkflowError>;

    async fn adopt_recipe_node_output(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        node_id: &AppName,
        input: &AppValidatedWorkflowValue,
        output: &AppValidatedWorkflowValue,
        output_claim_owner_id: &str,
        output_claim_epoch: u64,
        output_persisted_at_ms: i64,
    ) -> Result<AppRecipeCanonicalNodeAdmission, AppWorkflowError>;

    async fn fence_recipe_node_output(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        node_id: &AppName,
        permit: &AppRecipeCanonicalNodePermit,
    ) -> Result<(), AppWorkflowError>;

    /// Validate after waiting for a task lock without acquiring that same
    /// non-reentrant file lock again. The borrowed guard proves exclusion.
    async fn fence_recipe_node_output_under_task_guard(
        &self,
        _scope: &ScopeRef,
        _task_id: &str,
        _run: &AppRecipeAttachedRun,
        _node_id: &AppName,
        _permit: &AppRecipeCanonicalNodePermit,
        _guard: &AppWorkflowTaskGuard,
    ) -> Result<(), AppWorkflowError> {
        Err(AppWorkflowError::RecipeBindingUnavailable)
    }

    async fn settle_recipe_node(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        node_id: &AppName,
        permit: AppRecipeCanonicalNodePermit,
        output: &AppValidatedWorkflowValue,
        persisted_output: AppRecipePersistedNodeOutput,
    ) -> Result<(), AppWorkflowError>;

    async fn skip_recipe_nodes(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        node_ids: &[AppName],
    ) -> Result<(), AppWorkflowError>;

    async fn recipe_run_disposition(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
    ) -> Result<AppRecipeCanonicalRunDisposition, AppWorkflowError>;

    async fn verify_recipe_schedule_settled(
        &self,
        scope: &ScopeRef,
        task_id: &str,
        run: &AppRecipeAttachedRun,
        root_output: &AppValidatedWorkflowValue,
    ) -> Result<(), AppWorkflowError>;
}

