const DEFAULT_RUNNER_AGENT: &str = super::authoring_catalog::DEFAULT_APP_WORKFLOW_AGENT;

fn authorize_declared_runner(
    grant: &super::records::AppGrantRevision,
    agent: Option<&AppName>,
    personality: Option<&AppName>,
) -> Result<(), AppWorkflowError> {
    let runner = agent.map(AppName::as_str).unwrap_or(DEFAULT_RUNNER_AGENT);
    let required = AppReference::parse(format!("agent:{runner}"))?;
    if !grant
        .granted_agents
        .iter()
        .any(|granted| granted == &required)
    {
        return Err(AppWorkflowError::GrantMissingDeclaredAgent);
    }
    if let Some(personality) = personality {
        let required = AppReference::parse(format!("personality:{personality}"))?;
        if !grant
            .granted_personalities
            .iter()
            .any(|granted| granted == &required)
        {
            return Err(AppWorkflowError::GrantMissingDeclaredPersonality);
        }
    }
    Ok(())
}

/// Pure, current-grant eligibility used by bounded discovery before it
/// advertises an action. Runtime launch remains authoritative and separately
/// resolves the current agent definition and complete authority intersection.
pub(crate) fn declared_workflow_is_grant_eligible(
    grant: &super::records::AppGrantRevision,
    workflow: &AppManifestWorkflow,
) -> bool {
    authorize_declared_runner(
        grant,
        workflow.agent.as_ref(),
        workflow.personality.as_ref(),
    )
    .is_ok()
        && workflow.uses.iter().all(|tool| {
            super::tool_catalog::canonical_app_tool_ref(tool.as_str())
                .ok()
                .is_some_and(|required| grant.granted_tools.contains(&required))
        })
}
