#[derive(Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct AppWorkflowTaskBinding {
    pub schema: String,
    pub task_id: String,
    /// Scheduled occurrences share a task, never execution authority.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recurring: Option<AppRecurringOccurrence>,
    pub invocation: AppActionInvocation<Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub brokered_transfer_receipt: Option<AppCompositionTransferReceipt>,
    /// Complete A ∩ B transfer ceiling for brokered input. The field lives
    /// only in the authenticated task sidecar; the public receipt carries its
    /// digest, never authority to reconstruct or widen it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub brokered_transfer_policy: Option<AppDataHandlingPolicy>,
    /// Content-free exact behavior/grant identity minted only by the durable
    /// scheduler. It is reopened against the immutable manifest, current grant
    /// and scoped pause policy before execution/resume and provider I/O.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub background_behavior_binding: Option<AppWorkflowBehaviorBinding>,
    /// Event-specific counterpart to `background_behavior_binding`. Keeping
    /// the two axes distinct prevents a generic event caller from borrowing a
    /// reviewed schedule grant or vice versa. New bindings are mutually
    /// exclusive; omission preserves legacy sidecars.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub event_behavior_binding: Option<AppWorkflowEventBehaviorBinding>,
    /// Exact full policy of the admitted input bytes after intersecting the
    /// live destination grant, immutable manifest defaults, every present
    /// input-field override, and any brokered source ceiling. New bindings
    /// always seal it. `None` is retained only for compatibility with older
    /// direct/background sidecars and is never sufficient to make an old
    /// direct result a composable source.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub input_handling_policy: Option<AppDataHandlingPolicy>,
    pub installation_id: AppInstallationId,
    pub installation_generation: u64,
    pub package_revision_ref: AppReference,
    pub package_lock_digest: AppDigest,
    pub workflow_id: AppName,
    /// Present only for the exact installed `runner: recipe` selection. This
    /// is immutable lock evidence, not dispatch authority.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub recipe_binding: Option<AppLockedRecipeBinding>,
    pub trigger: AppManifestTrigger,
    /// Server-owned launch lane. V1 HTTP actions are foreground; schedule and
    /// event owners stamp background explicitly rather than inferring it from
    /// execution-id text.
    pub execution_lane: AppResourceExecutionLane,
    pub resolved_agent_id: AppReference,
    /// Exact scoped definition selected at launch. Absence is readable only
    /// for pre-binding sidecars and is never sufficient for execution/resume.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_agent_definition: Option<AppAgentDefinitionBinding>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_personality: Option<AppName>,
    /// Content address of the exact structured personality resolved at launch.
    /// Resume reconstructs from the sealed prompt-material record and never
    /// substitutes the current mutable scoped catalog entry.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_personality_digest: Option<AppDigest>,
    /// Complete digest tree for the workflow prompt, procedures, personality,
    /// agent definition and final procedure-narrowed tool ceiling.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prompt_material_binding: Option<AppPromptMaterialBinding>,
    /// Combined base capability authority plus exact agent and prompt identity.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub workflow_authority_digest: Option<AppDigest>,
    pub accepted_authority: AppWorkflowAuthoritySnapshot,
    /// Exact action/procedure catalog after intersecting every declared
    /// procedure `allowed-tools` ceiling. The broader authority snapshot is
    /// only an upper bound; execution may never recover tools removed here.
    pub effective_workflow_tools: BTreeSet<AppReference>,
    pub allowed_mutation_entities: BTreeSet<AppName>,
    pub result_entities: Vec<AppName>,
    /// Ordered digests of the exact move-only contribution authorities minted
    /// from the consumed owner approval at launch. The authorities themselves
    /// are never deserialized from this sidecar; every launch, recovery and
    /// terminal boundary reconstructs them from the current grant and the
    /// immutable package lock, then requires this exact digest sequence.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub contribution_binding_digests: Vec<AppDigest>,
    /// Reviewed primary output shape. Older packages may omit this and remain
    /// executable, but their results are intentionally not composable.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result_value_schema: Option<AppManifestInputSchema>,
    pub created_at: DateTime<Utc>,
}

