/// Opaque proof that one persisted canonical terminal belongs to the exact
/// app task/root execution resolved by this workflow owner. External callers
/// can inspect classification but cannot mint or substitute installation
/// authority.
pub struct AppCanonicalEventBehaviorSource {
    installation_id: AppInstallationId,
    background_origin: bool,
}

impl AppCanonicalEventBehaviorSource {
    pub fn installation_id(&self) -> &AppInstallationId {
        &self.installation_id
    }

    pub fn is_background_origin(&self) -> bool {
        self.background_origin
    }

    pub(crate) fn into_parts(self) -> (AppInstallationId, bool) {
        (self.installation_id, self.background_origin)
    }
}

fn classify_canonical_event_behavior_source(
    installation_id: AppInstallationId,
    observed_execution_id: &str,
    run_execution_id: &AppReference,
    canonical_root_execution_id: &AppReference,
    has_scheduled_behavior_binding: bool,
    has_event_behavior_binding: bool,
) -> Result<Option<AppCanonicalEventBehaviorSource>, AppWorkflowError> {
    if run_execution_id.as_str() != observed_execution_id
        || canonical_root_execution_id != run_execution_id
    {
        // Only the canonical root terminal is eligible. Child/delegated
        // executions may share the task binding but never inherit event
        // publication authority from it.
        return Ok(None);
    }
    match (has_scheduled_behavior_binding, has_event_behavior_binding) {
        (false, true) | (true, false) => Ok(Some(AppCanonicalEventBehaviorSource {
            installation_id,
            background_origin: true,
        })),
        (false, false) => Ok(Some(AppCanonicalEventBehaviorSource {
            installation_id,
            background_origin: false,
        })),
        (true, true) => Err(AppWorkflowError::CorruptBinding),
    }
}

impl std::fmt::Debug for AppWorkflowTaskBinding {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AppWorkflowTaskBinding")
            .field("schema", &self.schema)
            .field("task_id", &self.task_id)
            .field(
                "brokered_transfer_id",
                &self
                    .brokered_transfer_receipt
                    .as_ref()
                    .map(|receipt| &receipt.transfer_id),
            )
            .field("installation_id", &self.installation_id)
            .field("package_revision_ref", &self.package_revision_ref)
            .field("workflow_id", &self.workflow_id)
            .field(
                "recipe_binding_digest",
                &self
                    .recipe_binding
                    .as_ref()
                    .map(AppLockedRecipeBinding::binding_digest),
            )
            .field("resolved_agent_id", &self.resolved_agent_id)
            .field(
                "agent_definition_digest",
                &self
                    .resolved_agent_definition
                    .as_ref()
                    .map(|binding| &binding.definition_digest),
            )
            .field(
                "prompt_material_digest",
                &self
                    .prompt_material_binding
                    .as_ref()
                    .map(|binding| &binding.reconstruction_digest),
            )
            .field("workflow_authority_digest", &self.workflow_authority_digest)
            .field("resolved_personality", &self.resolved_personality)
            .field("effective_tool_count", &self.effective_workflow_tools.len())
            .field(
                "contribution_binding_count",
                &self.contribution_binding_digests.len(),
            )
            .field("created_at", &self.created_at)
            .finish_non_exhaustive()
    }
}

#[derive(Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
struct AppNativeToolResultCapacity {
    recipe_binding_digest: AppDigest,
    slots: usize,
}

#[derive(Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct AppWorkflowRunState {
    pub schema: String,
    /// Immutable identity of this exact sidecar. Child executions share the
    /// canonical root budget binding below, but never share their path or
    /// resolved owner identity.
    pub execution_id: AppReference,
    pub resolved_agent_id: AppReference,
    pub run_binding: AppRunBinding,
    pub authority: AppWorkflowAuthoritySnapshot,
    /// Latest content-free server admission for this execution's model
    /// context. Prompt/input bytes and runtime disclosure guards are never
    /// persisted; a resume must re-attest and replace this receipt.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_model_admission: Option<super::processing_boundary::AppDisclosureAdmissionReceipt>,
    /// Steps of the behavior's reviewed operation recipe that have completed,
    /// in order, each with the output it produced AFTER that output was
    /// validated against the step's reviewed schema.
    ///
    /// Durable because the recipe must survive a restart: the resolver
    /// re-derives the whole progression from this record on every turn rather
    /// than keeping a cursor, so a resumed run and a fresh one cannot
    /// disagree, and a lost or replayed response cannot advance the recipe by
    /// itself. Empty for every workflow that is not behavior-bound.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub behavior_recipe_progress: Vec<super::behavior_recipe::AppBehaviorStepOutcome>,
    /// Independently settled native effects. A member's receipt never stands
    /// in for workflow completion; terminal output remains in `result`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    native_commits: BTreeMap<AppReference, AppWorkflowNativeCommit>,
    /// Metadata-only native round checkpoints. Context points to protected
    /// tool records; posted content remains under the existing mutation owner.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    native_rounds: BTreeMap<AppReference, workflow_rounds::AppNativeRoundState>,
    /// Minted only by the canonical native owner from reviewed query shapes
    /// and attested source rows. The existing byte ceilings still apply.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    native_tool_result_capacity: Option<AppNativeToolResultCapacity>,
    /// Content-free evidence for exact result labels. It cannot reconstruct
    /// authority; resume must produce a fresh label and match it before result
    /// bytes may re-enter model/history/hidden-consumer paths.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tool_result_checkpoints: Vec<AppToolResultCheckpoint>,
    /// Exact bounded protected results. Persistence is admitted explicitly as
    /// protected labeled retention; this is the server membership authority
    /// used to reject forged pause checkpoints and modified result bytes.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub labeled_tool_results: Vec<AppLabeledToolResultRecord>,
    /// Control-plane-sealed raw provider completions. An unconsumed record is
    /// the only authority to finish settlement+labeling after a lost response;
    /// a consumed record retains bounded raw bytes so an exact action retry can
    /// recover the already-durable labeled result without provider I/O.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    effect_completion_intents: Vec<AppEffectCompletionIntent>,
    /// Bounded canonical governed-execution audit receipts (or an explicit
    /// receipt-unavailable marker after worker loss), bound to one effect and
    /// invocation. These records remain control-plane-only and are validated on
    /// every run-state read before completion recovery or disclosure.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    os_jail_audit_records: Vec<AppOsJailAuditRecord>,
    /// Common interactive owner settlement receipts, retained for both
    /// completed and uncertain outcomes. They are payload-minimal and bind the
    /// exact effect/session/action correlation without exposing raw evidence.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    interactive_receipt_records: Vec<AppInteractiveReceiptRecord>,
    /// Payload-free physical-session state, committed after the canonical
    /// effect dispatch start and before provider I/O. It contains no captured
    /// content, raw PID/window/device/package, or provider transport handle.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    interactive_session_records: Vec<AppInteractiveSessionRecord>,
    /// Durable recovery signal set when process-local root authority had to be
    /// released without completing canonical resource close. Startup/runtime
    /// recovery must reconcile held reservations before re-admission.
    #[serde(default)]
    pub resource_cleanup_pending: bool,
    /// Set when a model attempt of this run was refused on a ceiling that
    /// only the calendar clears (`monthly_tokens`, `monthly_cost`). The
    /// background scheduler reads it from a failed run and parks the
    /// behavior until the period ends instead of relaunching on its interval.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub period_ceiling_breach: Option<AppPeriodCeilingBreach>,
    /// Crash replay retains this generation. It advances only after trusted
    /// proven-unspent reconciliation, allowing the same logical terminal
    /// intent to receive a fresh reservation identity without reminting a
    /// permit for an ambiguous attempt.
    #[serde(default)]
    pub terminal_attempt_generation: u32,
    /// Payload-free proof that a cancellation-shaped runtime terminal crossed
    /// workflow admission. Artifact remains the terminal owner; this bit only
    /// lets public status distinguish conservative uncertainty from an
    /// independent ordinary failure.
    #[serde(default)]
    pub cancellation_outcome_uncertain: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub commit_intent: Option<AppWorkflowCommitIntent>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<AppActionResult<Value>>,
}

/// A period ceiling this run hit, kept payload-free on the run state.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AppPeriodCeilingBreach {
    /// The breached ceiling's canonical name (`monthly_tokens`, `monthly_cost`).
    pub ceiling: String,
    pub observed_at: DateTime<Utc>,
}

/// The period ceiling behind a workflow error, if that is what it is. A
/// monthly ceiling clears when the month does and nothing a retry can do
/// sooner; every other denial is this run's own failure.
pub fn period_ceiling_breach_of(error: &AppWorkflowError) -> Option<AppResourceBreach> {
    match error {
        AppWorkflowError::Resource(AppResourceAuthorityError::Contract(
            AppResourceContractError::ReservationDenied(
                breach @ (AppResourceBreach::MonthlyTokens | AppResourceBreach::MonthlyCost),
            ),
        )) => Some(*breach),
        _ => None,
    }
}

impl std::fmt::Debug for AppWorkflowRunState {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AppWorkflowRunState")
            .field("schema", &self.schema)
            .field("execution_id", &self.execution_id)
            .field("resolved_agent_id", &self.resolved_agent_id)
            .field("tool_result_count", &self.labeled_tool_results.len())
            .field(
                "effect_completion_intent_count",
                &self.effect_completion_intents.len(),
            )
            .field("os_jail_audit_count", &self.os_jail_audit_records.len())
            .field(
                "interactive_receipt_count",
                &self.interactive_receipt_records.len(),
            )
            .field(
                "interactive_session_count",
                &self.interactive_session_records.len(),
            )
            .field("resource_cleanup_pending", &self.resource_cleanup_pending)
            .field(
                "terminal_attempt_generation",
                &self.terminal_attempt_generation,
            )
            .field("has_commit_intent", &self.commit_intent.is_some())
            .field("has_result", &self.result.is_some())
            .finish_non_exhaustive()
    }
}

