impl AppInteractiveRunStateSnapshot {
    /// Artifact owns run terminal truth. If it is terminal before the physical
    /// receipt lands, expose conservative uncertainty and close controls
    /// without rewriting a durable stop declaration.
    pub fn apply_terminal_run_truth(&mut self) {
        let active_profile = self.current_session.as_ref().and_then(|session| {
            matches!(
                session.phase,
                AppInteractiveSessionPhase::Active | AppInteractiveSessionPhase::StopRequested
            )
            .then_some(session.profile)
        });
        if let Some(session) = self.current_session.as_mut() {
            if active_profile.is_some() {
                session.phase = AppInteractiveSessionPhase::OutcomeUncertain;
            }
        }
        for availability in &mut self.owner_availability {
            if matches!(
                availability.state,
                AppInteractiveOwnerAvailabilityState::Conditional
                    | AppInteractiveOwnerAvailabilityState::Active
                    | AppInteractiveOwnerAvailabilityState::Stopping
            ) {
                availability.state = AppInteractiveOwnerAvailabilityState::Unavailable;
                availability.unavailable_reason =
                    Some(AppInteractiveOwnerUnavailableReason::RunTerminal);
            }
        }
        if self.declared_stop_state.phase != AppInteractiveDeclaredStopPhase::Requested {
            self.declared_stop_state = AppInteractiveDeclaredStopState {
                phase: AppInteractiveDeclaredStopPhase::Unavailable,
                session_ref: None,
                stop_ref: None,
                requested_at: None,
                unavailable_reason: Some(AppInteractiveStopUnavailableReason::RunTerminal),
            };
        }
        self.stop_available = false;
    }
}

const APP_INTERACTIVE_READ_PROFILES: [AppInteractiveExecutionProfile; 3] = [
    AppInteractiveExecutionProfile::BrowserSession,
    AppInteractiveExecutionProfile::MacosHost,
    AppInteractiveExecutionProfile::AndroidDevice,
];

fn interactive_profile_dependency_ref(profile: AppInteractiveExecutionProfile) -> &'static str {
    match profile {
        AppInteractiveExecutionProfile::BrowserSession => "capability:browser",
        AppInteractiveExecutionProfile::MacosHost => "capability:macos-ui-automation",
        AppInteractiveExecutionProfile::AndroidDevice => "capability:android_snapshot",
    }
}

fn interactive_target_kind(profile: AppInteractiveExecutionProfile) -> AppInteractiveTargetKind {
    match profile {
        AppInteractiveExecutionProfile::BrowserSession => AppInteractiveTargetKind::IsolatedBrowser,
        AppInteractiveExecutionProfile::MacosHost => {
            AppInteractiveTargetKind::ReviewedMacosApplication
        },
        AppInteractiveExecutionProfile::AndroidDevice => {
            AppInteractiveTargetKind::ReviewedAndroidApplication
        },
    }
}

fn interactive_owner_availability(
    task: &AppWorkflowTaskBinding,
    current_record: Option<&AppInteractiveSessionRecord>,
    current_session: Option<&AppInteractiveSessionState>,
    terminal_receipt: bool,
    live: AppInteractiveLiveSessionAvailability,
    now: DateTime<Utc>,
) -> Result<Vec<AppInteractiveOwnerAvailability>, AppWorkflowError> {
    let mut availability = Vec::with_capacity(APP_INTERACTIVE_READ_PROFILES.len());
    for profile in APP_INTERACTIVE_READ_PROFILES {
        let declared = task
            .effective_workflow_tools
            .iter()
            .any(|reference| reference.as_str() == interactive_profile_dependency_ref(profile));
        let is_current = current_record.is_some_and(|record| record.profile == profile);
        if is_current && !declared {
            return Err(AppWorkflowError::CorruptBinding);
        }
        let (state, unavailable_reason) = if !declared {
            (
                AppInteractiveOwnerAvailabilityState::Unavailable,
                Some(AppInteractiveOwnerUnavailableReason::NotDeclared),
            )
        } else if !is_current {
            (AppInteractiveOwnerAvailabilityState::Conditional, None)
        } else if terminal_receipt {
            (AppInteractiveOwnerAvailabilityState::Settled, None)
        } else if current_record.is_some_and(|record| now >= record.expires_at) {
            (
                AppInteractiveOwnerAvailabilityState::Unavailable,
                Some(AppInteractiveOwnerUnavailableReason::SessionExpired),
            )
        } else if current_session
            .is_some_and(|session| session.phase == AppInteractiveSessionPhase::StopRequested)
            || matches!(
                live,
                AppInteractiveLiveSessionAvailability::OwnerStopSignalled
                    | AppInteractiveLiveSessionAvailability::Closing
            )
        {
            (AppInteractiveOwnerAvailabilityState::Stopping, None)
        } else if live == AppInteractiveLiveSessionAvailability::Active {
            (AppInteractiveOwnerAvailabilityState::Active, None)
        } else {
            (
                AppInteractiveOwnerAvailabilityState::Unavailable,
                Some(AppInteractiveOwnerUnavailableReason::RuntimeOwnerUnavailable),
            )
        };
        availability.push(AppInteractiveOwnerAvailability {
            profile,
            state,
            unavailable_reason,
        });
    }
    Ok(availability)
}

fn interactive_declared_stop_state(
    stop: Option<&AppInteractiveStopReceipt>,
    current_session: Option<&AppInteractiveSessionState>,
    live: AppInteractiveLiveSessionAvailability,
) -> AppInteractiveDeclaredStopState {
    if let Some((stop, _session)) = stop
        .zip(current_session)
        .filter(|(stop, session)| stop.session_ref == session.session_ref)
    {
        return AppInteractiveDeclaredStopState {
            phase: AppInteractiveDeclaredStopPhase::Requested,
            session_ref: Some(stop.session_ref.clone()),
            stop_ref: Some(stop.stop_ref.clone()),
            requested_at: Some(stop.requested_at.clone()),
            unavailable_reason: None,
        };
    }
    if current_session.is_some_and(|session| session.phase == AppInteractiveSessionPhase::Active)
        && live == AppInteractiveLiveSessionAvailability::Active
    {
        return AppInteractiveDeclaredStopState {
            phase: AppInteractiveDeclaredStopPhase::Available,
            session_ref: None,
            stop_ref: None,
            requested_at: None,
            unavailable_reason: None,
        };
    }
    let unavailable_reason = if current_session.is_none() {
        AppInteractiveStopUnavailableReason::NoCurrentSession
    } else if current_session
        .is_some_and(|session| session.phase != AppInteractiveSessionPhase::Active)
    {
        AppInteractiveStopUnavailableReason::SessionTerminal
    } else if matches!(
        live,
        AppInteractiveLiveSessionAvailability::OwnerStopSignalled
            | AppInteractiveLiveSessionAvailability::Closing
    ) {
        AppInteractiveStopUnavailableReason::OwnerClosing
    } else {
        AppInteractiveStopUnavailableReason::RuntimeOwnerUnavailable
    };
    AppInteractiveDeclaredStopState {
        phase: AppInteractiveDeclaredStopPhase::Unavailable,
        session_ref: None,
        stop_ref: None,
        requested_at: None,
        unavailable_reason: Some(unavailable_reason),
    }
}

