/// Serializable minimum authority needed to keep a task permanently narrowed.
/// Actor/session authentication is deliberately absent; every consequential
/// boundary mints fresh task-execution evidence and re-runs the intersection.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AppWorkflowAuthoritySnapshot {
    pub scope_binding_ref: super::models::AppScopeBindingRef,
    pub installation_id: AppInstallationId,
    pub installation_generation: u64,
    pub package_revision_ref: AppReference,
    pub grant_revision: AppRevision,
    pub schema_revision: AppRevision,
    pub data_handling_policy_digest: AppDigest,
    pub authority_digest: AppDigest,
    pub effective_tools: BTreeSet<AppReference>,
    pub effective_context_reads: BTreeSet<AppReference>,
    pub effective_data_handling_policy: AppDataHandlingPolicy,
    pub effective_background_execution: AppBackgroundExecution,
    pub effective_network_policy: AppNetworkPolicy,
    pub effective_resources: AppResourceCeiling,
}

impl AppWorkflowAuthoritySnapshot {
    fn from_resolved(
        authority: &ResolvedAppAuthority,
        data_handling_policy_digest: AppDigest,
    ) -> Result<Self, AppWorkflowError> {
        let authority_digest = AppDigest::blake3(&canonical_json_bytes(&json!({
            "scope_binding_ref": &authority.scope_binding_ref,
            "installation_id": &authority.installation_id,
            "installation_generation": authority.installation_generation,
            "package_revision_ref": &authority.package_revision_ref,
            "grant_revision": authority.grant_revision,
            "schema_revision": authority.schema_revision,
            "data_handling_policy_digest": &data_handling_policy_digest,
            "effective_tools": &authority.effective_tools,
            "effective_context_reads": &authority.effective_context_reads,
            "effective_data_handling_policy": &authority.effective_data_handling_policy,
            "effective_background_execution": &authority.effective_background_execution,
            "effective_network_policy": &authority.effective_network_policy,
            "effective_resources": &authority.effective_resources,
        }))?);
        Ok(Self {
            scope_binding_ref: authority.scope_binding_ref.clone(),
            installation_id: authority.installation_id.clone(),
            installation_generation: authority.installation_generation,
            package_revision_ref: authority.package_revision_ref.clone(),
            grant_revision: authority.grant_revision,
            schema_revision: authority.schema_revision,
            data_handling_policy_digest,
            authority_digest,
            effective_tools: authority.effective_tools.clone(),
            effective_context_reads: authority.effective_context_reads.clone(),
            effective_data_handling_policy: authority.effective_data_handling_policy.clone(),
            effective_background_execution: authority.effective_background_execution.clone(),
            effective_network_policy: authority.effective_network_policy.clone(),
            effective_resources: authority.effective_resources.clone(),
        })
    }

    fn ceiling(&self) -> AppAuthorityCeiling {
        AppAuthorityCeiling {
            tools: self.effective_tools.clone(),
            context_reads: self.effective_context_reads.clone(),
            data_handling_policy: self.effective_data_handling_policy.clone(),
            background_execution: self.effective_background_execution.clone(),
            network_policy: self.effective_network_policy.clone(),
            resources: self.effective_resources.clone(),
        }
    }

    fn digest_matches(&self) -> Result<bool, AppWorkflowError> {
        let digest = AppDigest::blake3(&canonical_json_bytes(&json!({
            "scope_binding_ref": &self.scope_binding_ref,
            "installation_id": &self.installation_id,
            "installation_generation": self.installation_generation,
            "package_revision_ref": &self.package_revision_ref,
            "grant_revision": self.grant_revision,
            "schema_revision": self.schema_revision,
            "data_handling_policy_digest": &self.data_handling_policy_digest,
            "effective_tools": &self.effective_tools,
            "effective_context_reads": &self.effective_context_reads,
            "effective_data_handling_policy": &self.effective_data_handling_policy,
            "effective_background_execution": &self.effective_background_execution,
            "effective_network_policy": &self.effective_network_policy,
            "effective_resources": &self.effective_resources,
        }))?);
        Ok(digest == self.authority_digest)
    }
}

