/// Closed, generation-bound cancellation request. The run identity is carried
/// by the URL and authenticated workflow control, never by caller-supplied
/// task/execution identifiers.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AppActionCancellationRequest {
    pub expected_generation: u64,
    pub idempotency_key: AppReference,
}

/// Stable response-loss replay receipt. `Cancelling` proves the intent is
/// durable; `Cancelled` is minted only from the protected pre-I/O proof and is
/// returned only after Artifact has committed the canonical terminal state.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AppActionCancellationReceipt {
    pub protocol_version: AppProtocolVersion,
    pub run_ref: AppReference,
    pub generation: u64,
    pub idempotency_key: AppReference,
    pub status: AppRunStatus,
    pub requested_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub(crate) enum AppActionCancellationOwner {
    Workflow,
    Recipe,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub(crate) struct AppActionCancellationControl {
    schema: String,
    run_ref: AppReference,
    execution_id: AppReference,
    task_binding_digest: AppDigest,
    generation: u64,
    expected_generation: u64,
    idempotency_key: AppReference,
    owner: AppActionCancellationOwner,
    before_io_proven: bool,
    requested_at: DateTime<Utc>,
}

impl AppActionCancellationControl {
    pub(crate) fn owner(&self) -> AppActionCancellationOwner {
        self.owner
    }

    pub(crate) fn before_io_proven(&self) -> bool {
        self.before_io_proven
    }

    pub(crate) fn receipt(&self) -> AppActionCancellationReceipt {
        AppActionCancellationReceipt {
            protocol_version: AppProtocolVersion::V1,
            run_ref: self.run_ref.clone(),
            generation: self.generation,
            idempotency_key: self.idempotency_key.clone(),
            status: if self.before_io_proven {
                AppRunStatus::Cancelled
            } else {
                AppRunStatus::Cancelling
            },
            requested_at: self.requested_at,
        }
    }
}

pub(crate) struct AppBrokeredWorkflowLaunch {
    pub(crate) launch: AppWorkflowLaunch,
    pub(crate) transfer_policy: AppDataHandlingPolicy,
    /// Result bytes existed but the recovery read was denied by current
    /// disclosure policy. Preserve that distinction across the redacting
    /// composition adapter without exposing canonical result metadata.
    pub(crate) result_was_withheld: bool,
    /// Exact full policy for a synchronously returned result, including
    /// reviewed output-field restrictions and its actual joined labels. This
    /// stays server-only so outer compiled adapters can guard the bytes rather
    /// than reconstructing policy from a digest in JSON.
    pub(crate) result_policy: Option<AppDataHandlingPolicy>,
}

pub(crate) enum AppBrokeredWorkflowLaunchError {
    CancelledBeforeDispatch,
    PreDispatch(AppWorkflowError),
    EffectUncertain(AppWorkflowError),
}

/// Stage-aware result of the direct personal-agent launch adapter.
///
/// The inner error remains server-only. A compiled handler projects it to a
/// stable retry class and never serializes implementation details. Once the
/// final start boundary is entered, the deterministic run handle is retained
/// even if the runtime response is lost so the owner can recover the same
/// logical action without risking a duplicate effect.
pub(crate) enum AppPersonalAgentWorkflowLaunchError {
    CancelledBeforeDispatch,
    /// The original physical-provider/session fence stopped being current.
    /// No app identity or result may be serialized to whichever provider is
    /// current now; the caller can recover with the same idempotency key from
    /// a freshly admitted turn.
    PublicationDenied {
        effect_uncertain: bool,
    },
    PreDispatch(AppWorkflowError),
    /// The deterministic task shell already exists (or its existence could
    /// not be read), but the sealed binding could not be proven. An earlier
    /// same-key attempt may have crossed the effect boundary, while exposing a
    /// run handle before exact binding validation would disclose an untrusted
    /// identity. Project uncertainty without a handle and retry only according
    /// to the underlying stable error class.
    ExistingRunStateUnknown {
        error: AppWorkflowError,
    },
    ExistingNotStarted {
        error: AppWorkflowError,
        run_handle: AppRunHandle,
        guard_policy: AppDataHandlingPolicy,
    },
    EffectUncertain {
        error: AppWorkflowError,
        run_handle: AppRunHandle,
        guard_policy: AppDataHandlingPolicy,
    },
}

/// Model-safe projection of a direct personal-agent action launch. Result
/// provenance and effect receipts remain in the canonical task sidecars; only
/// an output admitted by the current destination policy and physical caller
/// audience is projected here.
pub(crate) struct AppPersonalAgentWorkflowLaunch {
    pub(crate) run_handle: AppRunHandle,
    pub(crate) result: Option<AppModelActionResult<Value>>,
    pub(crate) result_withheld_by_policy: bool,
    /// Complete guard for every returned byte. Even a non-result launch
    /// handle inherits the exact sealed input policy; a synchronous typed
    /// result adds its output policy on top.
    guard_policy: AppDataHandlingPolicy,
}

impl AppPersonalAgentWorkflowLaunch {
    pub(crate) fn into_parts(
        self,
    ) -> (
        AppRunHandle,
        Option<AppModelActionResult<Value>>,
        bool,
        AppDataHandlingPolicy,
    ) {
        (
            self.run_handle,
            self.result,
            self.result_withheld_by_policy,
            self.guard_policy,
        )
    }
}

/// Minimum source shape needed to recover an already-sealed brokered launch
