/// Non-wire proof that a server-owned schedule/event ingress selected one
/// exact protected invocation. HTTP callers cannot deserialize or mint this
/// value, and the common launch path rechecks every bound field after loading
/// the immutable manifest trigger.
pub struct AppBackgroundLaunchAuthority {
    scope_binding_ref: super::models::AppScopeBindingRef,
    installation_id: AppInstallationId,
    trigger: AppManifestTrigger,
    launch_ref: AppReference,
    input_source: AppDataSource,
    input_digest: AppDigest,
    source_refs_digest: AppDigest,
    behavior_binding: Option<AppWorkflowBehaviorBinding>,
    event_behavior_binding: Option<AppWorkflowEventBehaviorBinding>,
    expires_at: DateTime<Utc>,
}

impl std::fmt::Debug for AppBackgroundLaunchAuthority {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AppBackgroundLaunchAuthority")
            .field("installation_id", &self.installation_id)
            .field("trigger", &self.trigger)
            .field("launch_ref", &self.launch_ref)
            .field("input_source", &self.input_source)
            .field("expires_at", &self.expires_at)
            .finish_non_exhaustive()
    }
}

impl AppBackgroundLaunchAuthority {
    fn from_server_owner(
        authenticated: &AuthenticatedAppScope,
        installation_id: AppInstallationId,
        trigger: AppManifestTrigger,
        launch_ref: AppReference,
        input: &AppDataEnvelope<Value>,
        now: DateTime<Utc>,
    ) -> Result<Self, AppWorkflowError> {
        authenticated.ensure_live_at(&now)?;
        let expected_source = match trigger {
            AppManifestTrigger::Schedule => AppDataSource::AppStore,
            AppManifestTrigger::Event => AppDataSource::ExternalAdapter,
            AppManifestTrigger::User => {
                return Err(AppWorkflowError::BackgroundLaunchAuthorityRequired);
            },
        };
        if input.source != expected_source || input.source_refs.is_empty() {
            return Err(AppWorkflowError::UnsupportedInputSource);
        }
        let input_digest = AppDigest::blake3(&canonical_json_bytes(&input.value)?);
        let source_refs_digest = AppDigest::blake3(&canonical_json_bytes(&serde_json::to_value(
            &input.source_refs,
        )?)?);
        let expires_at = std::cmp::min(
            authenticated.expires_at().to_owned(),
            now.checked_add_signed(Duration::minutes(10))
                .ok_or(AppWorkflowError::TimeOverflow)?,
        );
        if expires_at <= now {
            return Err(AppWorkflowError::BackgroundLaunchAuthorityExpired);
        }
        Ok(Self {
            scope_binding_ref: authenticated.scope_binding_ref().clone(),
            installation_id,
            trigger,
            launch_ref,
            input_source: expected_source,
            input_digest,
            source_refs_digest,
            behavior_binding: None,
            event_behavior_binding: None,
            expires_at,
        })
    }

    pub fn from_server_schedule(
        authenticated: &AuthenticatedAppScope,
        installation_id: AppInstallationId,
        launch_ref: AppReference,
        input: &AppDataEnvelope<Value>,
        now: DateTime<Utc>,
    ) -> Result<Self, AppWorkflowError> {
        Self::from_server_owner(
            authenticated,
            installation_id,
            AppManifestTrigger::Schedule,
            launch_ref,
            input,
            now,
        )
    }

    #[cfg(test)]
    pub(crate) fn from_server_event(
        authenticated: &AuthenticatedAppScope,
        installation_id: AppInstallationId,
        launch_ref: AppReference,
        input: &AppDataEnvelope<Value>,
        now: DateTime<Utc>,
    ) -> Result<Self, AppWorkflowError> {
        Self::from_server_owner(
            authenticated,
            installation_id,
            AppManifestTrigger::Event,
            launch_ref,
            input,
            now,
        )
    }

    pub(crate) fn from_server_behavior_schedule(
        authenticated: &AuthenticatedAppScope,
        installation_id: AppInstallationId,
        launch_ref: AppReference,
        input: &AppDataEnvelope<Value>,
        grant: AppBehaviorGrant,
        source_policy: AppDataHandlingPolicy,
        lease_expires_at: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Self, AppWorkflowError> {
        let mut authority = Self::from_server_owner(
            authenticated,
            installation_id,
            AppManifestTrigger::Schedule,
            launch_ref.clone(),
            input,
            now,
        )?;
        validate_policy(&source_policy, &AppContractLimits::default())?;
        if lease_expires_at <= now
            || AppDigest::blake3_canonical_json(&serde_json::to_value(&source_policy)?)?
                != input.handling_labels.policy_digest
        {
            return Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch);
        }
        authority.expires_at = authority.expires_at.min(lease_expires_at);
        authority.behavior_binding = Some(AppWorkflowBehaviorBinding {
            grant,
            launch_ref,
            source_policy,
        });
        Ok(authority)
    }

    pub(crate) fn from_server_event_behavior(
        authenticated: &AuthenticatedAppScope,
        installation_id: AppInstallationId,
        launch_ref: AppReference,
        input: &AppDataEnvelope<Value>,
        grant: AppEventBehaviorGrant,
        source_policy: AppDataHandlingPolicy,
        lease_expires_at: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Self, AppWorkflowError> {
        let mut authority = Self::from_server_owner(
            authenticated,
            installation_id,
            AppManifestTrigger::Event,
            launch_ref.clone(),
            input,
            now,
        )?;
        validate_policy(&source_policy, &AppContractLimits::default())?;
        if lease_expires_at <= now
            || AppDigest::blake3_canonical_json(&serde_json::to_value(&source_policy)?)?
                != input.handling_labels.policy_digest
        {
            return Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch);
        }
        authority.expires_at = authority.expires_at.min(lease_expires_at);
        authority.event_behavior_binding = Some(AppWorkflowEventBehaviorBinding {
            grant,
            launch_ref,
            source_policy,
        });
        Ok(authority)
    }

    fn validate(
        &self,
        authenticated: &AuthenticatedAppScope,
        installation_id: &AppInstallationId,
        trigger: AppManifestTrigger,
        action_id: &AppName,
        caller_ref: &AppReference,
        input: &AppDataEnvelope<Value>,
        now: DateTime<Utc>,
    ) -> Result<(), AppWorkflowError> {
        authenticated.ensure_live_at(&now)?;
        if now >= self.expires_at {
            return Err(AppWorkflowError::BackgroundLaunchAuthorityExpired);
        }
        if self.scope_binding_ref != *authenticated.scope_binding_ref()
            || &self.installation_id != installation_id
            || self.trigger != trigger
            || self.input_source != input.source
            || self.input_digest != AppDigest::blake3(&canonical_json_bytes(&input.value)?)
            || self.source_refs_digest
                != AppDigest::blake3(&canonical_json_bytes(&serde_json::to_value(
                    &input.source_refs,
                )?)?)
        {
            return Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch);
        }
        match (
            self.behavior_binding.as_ref(),
            self.event_behavior_binding.as_ref(),
        ) {
            (Some(binding), None)
                if trigger == AppManifestTrigger::Schedule
                    && binding.launch_ref == self.launch_ref
                    && binding.grant.action == *action_id
                    && caller_ref.as_str()
                        == format!("behavior:{}", binding.grant.behavior_id.as_str()) => {},
            (None, Some(binding))
                if trigger == AppManifestTrigger::Event
                    && binding.launch_ref == self.launch_ref
                    && binding.grant.action == *action_id
                    && caller_ref.as_str()
                        == format!(
                            "event-behavior:{}",
                            binding.grant.event_behavior_id.as_str()
                        ) => {},
            (Some(_), _) | (_, Some(_)) => {
                return Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch);
            },
            (None, None)
                if caller_ref.as_str().starts_with("behavior:")
                    || caller_ref.as_str().starts_with("event-behavior:") =>
            {
                return Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch);
            },
            (None, None) => {},
        }
        Ok(())
    }
}

