enum AppWorkflowInteractivePreparedOwner {
    Browser(AppBrowserPreparedAction),
    Macos(AppMacosPreparedWorkflowAction),
    Android(AppAndroidPreparedAction),
}

impl AppWorkflowInteractivePreparedOwner {
    fn is_macos(&self) -> bool {
        matches!(self, Self::Macos(_))
    }

    fn is_android(&self) -> bool {
        matches!(self, Self::Android(_))
    }

    fn attest_effect_target(
        &self,
        tool_ref: &AppReference,
        primitive: &super::package_lock::AppLockedPrimitiveBinding,
        action: &super::package_lock::AppLockedPrimitiveActionBinding,
    ) -> Result<super::effect_kernel::AppEffectPhysicalTarget, AppEffectKernelError> {
        match self {
            Self::Browser(owner) => owner.attest_effect_target(tool_ref, primitive, action),
            Self::Macos(owner) => owner.attest_effect_target(tool_ref, primitive, action),
            Self::Android(owner) => owner.attest_effect_target(tool_ref, primitive, action),
        }
    }
}

