    #[test]
    fn action_result_receipt_keeps_source_run_evidence_server_internal() {
        let (mut receipt, installation, mut invocation) = brokered_receipt_fixture();
        let run_ref = AppReference::parse(format!(
            "{APP_ACTION_RUN_REF_PREFIX}task_app_{}",
            "a".repeat(64)
        ))
        .unwrap();
        let fields = vec![AppFieldPath::parse("name").unwrap()];
        receipt.source_records.clear();
        receipt.source_action_result = Some(AppSourceActionResultFence {
            source_run_ref: run_ref.clone(),
            source_task_binding_digest: AppDigest::blake3(b"source-task"),
            source_grant_policy_digest: AppDigest::blake3(b"source-grant"),
            output_revision: AppRevision::new(1).unwrap(),
            result_digest: AppDigest::blake3(b"source-result"),
            fields: fields.clone(),
        });
        receipt.schema_version = LEGACY_ACTION_TRANSFER_SCHEMA_VERSION;
        invocation
            .input
            .source_refs
            .retain(|source| source.kind != AppSourceRefKind::EntityField);
        invocation.input.source_refs.push(AppSourceRef {
            kind: AppSourceRefKind::ExternalReceipt,
            reference: AppReference::parse("event:upstream").unwrap(),
            revision: None,
            fields: Vec::new(),
        });
        let upstream = invocation
            .input
            .source_refs
            .iter()
            .filter(|source| {
                !(source.kind == AppSourceRefKind::ExternalReceipt
                    && source.reference == receipt.transfer_id)
            })
            .collect::<Vec<_>>();
        receipt.source_refs_digest = Some(
            AppDigest::blake3_canonical_json(&serde_json::to_value(upstream).unwrap()).unwrap(),
        );
        invocation.input.handling_labels.provenance_digest =
            AppDigest::blake3_canonical_json(&serde_json::to_value(&receipt).unwrap()).unwrap();
        assert!(validate_brokered_transfer_receipt(
            &receipt,
            &installation.installation_id,
            &installation,
            &invocation,
        )
        .is_ok());

        receipt.source_action_result.as_mut().unwrap().fields = vec![
            AppFieldPath::parse("zeta").unwrap(),
            AppFieldPath::parse("alpha").unwrap(),
        ];
        assert!(validate_brokered_transfer_receipt(
            &receipt,
            &installation.installation_id,
            &installation,
            &invocation,
        )
        .is_err());
    }

