    #[test]
    fn persisted_brokered_invocation_requires_its_exact_durable_receipt() {
        let (receipt, installation, invocation) = brokered_receipt_fixture();
        let mut task = fixture_task();
        task.invocation = invocation.clone();
        task.brokered_transfer_receipt = Some(receipt);
        task.brokered_transfer_policy = Some(brokered_policy_fixture());
        task.installation_id = installation.installation_id.clone();
        task.installation_generation = installation.lifecycle.generation;
        task.package_revision_ref = installation.package_revision_ref.clone();
        task.accepted_authority.scope_binding_ref = invocation.input.scope_binding_ref.clone();
        task.accepted_authority.installation_id = installation.installation_id.clone();
        task.accepted_authority.installation_generation = installation.lifecycle.generation;
        task.accepted_authority.package_revision_ref = installation.package_revision_ref.clone();
        task.accepted_authority.schema_revision = invocation.input.schema_revision;
        task.accepted_authority.grant_revision = invocation.input.grant_revision;
        task.accepted_authority.data_handling_policy_digest = AppDigest::blake3(b"live-b-grant");
        task.accepted_authority.effective_data_handling_policy = brokered_policy_fixture();

        let mut reconstructed = invocation.clone();
        normalize_persisted_invocation_for_execution(
            &task,
            &mut reconstructed,
            AppDataClassification::Secret,
            AppModelProcessing::LocalOnly,
        )
        .unwrap();
        assert_eq!(reconstructed.input.source, AppDataSource::BrokeredTransfer);

        let mut missing_expiry = invocation.clone();
        missing_expiry.input.expires_at = None;
        assert!(matches!(
            normalize_persisted_invocation_for_execution(
                &task,
                &mut missing_expiry,
                AppDataClassification::Secret,
                AppModelProcessing::LocalOnly,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));

        task.brokered_transfer_receipt = None;
        let mut missing_receipt = invocation.clone();
        assert!(matches!(
            normalize_persisted_invocation_for_execution(
                &task,
                &mut missing_receipt,
                AppDataClassification::Secret,
                AppModelProcessing::LocalOnly,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));

        let mut direct_task = fixture_task();
        direct_task.invocation.input.expires_at = Some("2099-01-01T00:00:00Z".parse().unwrap());
        let mut direct_invocation = direct_task.invocation.clone();
        assert!(matches!(
            normalize_persisted_invocation_for_execution(
                &direct_task,
                &mut direct_invocation,
                AppDataClassification::Secret,
                AppModelProcessing::LocalOnly,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));
    }

    fn immutable_material_fixture(
        retained_bytes: usize,
        authority_seed: &[u8],
    ) -> Arc<AppImmutableWorkflowMaterial> {
        use super::super::{
            manifest::{
                build_app_package_candidate, canonical_view_schema_digest, tests::valid_bundle,
                AppDependencyKind, AppPackageLimits,
            },
            package_lock::{lock_app_package_dependencies, AppVerifiedRegistryDependency},
            package_staging::materialize_test_staged_package,
            records::{AppCompatibilityRequirement, AppPackageSourceKind},
            registry::tests::{authenticated_scope, canonical_tempdir, reference, time},
            schema_compiler::canonical_entity_schema_digest,
        };

        let temporary = canonical_tempdir();
        let workspace = ArtifactV2Workspace::new(temporary.path());
        let authenticated = authenticated_scope("anonymous", "default");
        let candidate =
            build_app_package_candidate(valid_bundle(), &AppPackageLimits::default()).unwrap();
        let evidence = vec![
            AppVerifiedRegistryDependency::from_trusted_registry_bytes(
                AppDependencyKind::Contract,
                reference("contract:magician_contract"),
                "1.2.0".to_owned(),
                reference("contract-revision:42"),
                AppRevision::new(42).unwrap(),
                b"contract-v1.2.0",
            )
            .unwrap(),
            AppVerifiedRegistryDependency::from_trusted_registry_bytes(
                AppDependencyKind::Capability,
                reference("capability:content_search"),
                "1.4.3".to_owned(),
                reference("capability-revision:99"),
                AppRevision::new(99).unwrap(),
                b"content-search-v1.4.3",
            )
            .unwrap(),
        ];
        let package_lock =
            lock_app_package_dependencies(&candidate, evidence, &AppPackageLimits::default())
                .unwrap();
        let manifest = candidate.manifest().manifest();
        let package_revision = AppPackageRevision {
            package_id: reference("app:learning-plan"),
            semantic_version: manifest.version.clone(),
            content_digest: candidate.bundle_digest().clone(),
            manifest_schema_version: manifest.metadata.magician.app_manifest_version.clone(),
            authoring_sdk_version: manifest.metadata.magician.app_sdk_version.clone(),
            publisher_identity: reference("publisher:cache-fixture"),
            source_kind: AppPackageSourceKind::LocalVibedev,
            compatibility: vec![AppCompatibilityRequirement {
                contract: AppName::parse("magician_contract").unwrap(),
                requirement: "1".to_owned(),
            }],
            requested_authority_digest: AppDigest::blake3(authority_seed),
            requested_data_policy_digest: AppDigest::blake3(b"cache-policy"),
            dependency_lock_digest: package_lock.lock_digest().clone(),
            entity_schema_digest: canonical_entity_schema_digest(manifest).unwrap(),
            view_schema_digest: canonical_view_schema_digest(manifest).unwrap(),
            workflow_digest: AppDigest::blake3(b"cache-workflows"),
            verification_attestation_ref: Some(reference("attestation:cache-verification")),
            conformance_attestation_ref: reference("attestation:cache-conformance"),
            created_at: time(1),
        };
        let staged = materialize_test_staged_package(&workspace, authenticated.scope(), candidate);
        Arc::new(AppImmutableWorkflowMaterial {
            package_revision,
            package_lock,
            staged,
            registry_procedures: Vec::new(),
            retained_bytes,
        })
    }

    #[test]
    fn background_behavior_runtime_admission_is_fail_closed_and_clone_shared() {
        let temporary = super::super::registry::tests::canonical_tempdir();
        let service = AppWorkflowService::new(ArtifactV2Workspace::new(temporary.path()));
        let clone = service.clone();
        assert!(!service
            .background_behavior_runtime_admitted
            .load(Ordering::Acquire));
        clone.set_background_behavior_runtime_admission(true);
        assert!(service
            .background_behavior_runtime_admitted
            .load(Ordering::Acquire));
        service.set_background_behavior_runtime_admission(false);
        assert!(!clone
            .background_behavior_runtime_admitted
            .load(Ordering::Acquire));
    }

    #[test]
    fn deterministic_recipe_runtime_input_does_not_require_a_model_step() {
        let temporary = super::super::registry::tests::canonical_tempdir();
        // No router, provider, model profile or model budget is installed.
        let service = AppWorkflowService::new(ArtifactV2Workspace::new(temporary.path()));
        let (candidate, lock) = super::super::package_lock::tests::locked_native_recipe_fixture();
        let mut manifest = candidate.manifest().manifest().clone();
        let mut task = fixture_task();
        task.workflow_id = AppName::parse("build").unwrap();
        task.recipe_binding = lock.recipe_for_workflow(&task.workflow_id).cloned();
        let mut state = fixture_run_state(&task, "exec_root_1", "personal-assistant");
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest).unwrap(),
            AppRecipeAdmission::Deterministic
        ));

        // Reproduce the scheduled case that previously failed when shared
        // store/tool authorization asked for runtime input with zero steps.
        let town = super::super::package_staging::admit_package_directory(
            &std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../magician_data_v3/system/town_square/app")
                .canonicalize()
                .expect("canonical shipped package root"),
        )
        .unwrap();
        let mut behavior = town.manifest().manifest().app.behaviors[0].clone();
        behavior.operations.clear();
        behavior.steps.clear();
        task.background_behavior_binding = Some(AppWorkflowBehaviorBinding {
            grant: AppBehaviorGrant {
                behavior_id: behavior.id.clone(),
                purpose: behavior.purpose.clone(),
                action: behavior.action.clone(),
                input_selector_digest: AppDigest::blake3(b"fixture-selector"),
                operations: Vec::new(),
                steps_digest: None,
                output_schema_digest: None,
                min_interval_seconds: 60,
                resources: super::super::records::AppBehaviorResourceCeiling {
                    max_tokens_per_run: 0,
                    max_cost_microusd_per_run: 0,
                    max_active_seconds_per_run: 60,
                    max_tokens_per_month: 0,
                    max_cost_microusd_per_month: 0,
                    max_starts_per_period: 60,
                    period_seconds: 3600,
                    max_causation_depth: 1,
                    max_spend_depth: 1,
                    max_contribution_proposals_per_run: 0,
                },
                reviewed_request_digest: AppDigest::blake3(b"fixture-behavior"),
            },
            launch_ref: AppReference::parse("behavior-fire:fixture").unwrap(),
            source_policy: task
                .accepted_authority
                .effective_data_handling_policy
                .clone(),
        });
        manifest.app.behaviors = vec![behavior];
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest).unwrap(),
            AppRecipeAdmission::Deterministic
        ));

        let binding = task.background_behavior_binding.as_mut().unwrap();
        binding.grant.steps_digest = Some(AppDigest::blake3(b"substituted-steps"));
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest),
            Err(AppWorkflowError::StaleBehaviorRecipeBinding)
        ));
        task.background_behavior_binding
            .as_mut()
            .unwrap()
            .grant
            .steps_digest = None;
        state.behavior_recipe_progress.push(
            super::super::behavior_recipe::AppBehaviorStepOutcome {
                step: AppName::parse("unexpected-model-output").unwrap(),
                output: json!({"body":"unadmitted"}),
                spent_output_tokens: 1,
            },
        );
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest),
            Err(AppWorkflowError::StaleBehaviorRecipeBinding)
        ));
        state.behavior_recipe_progress.clear();
        manifest.app.behaviors[0]
            .operations
            .push(AppName::parse("compose_post").unwrap());
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest),
            Err(AppWorkflowError::BackgroundBehaviorOperationStepBindingRequired)
        ));
        manifest.app.behaviors[0].operations.clear();
        task.recipe_binding = None;
        assert!(matches!(
            service.admit_recipe_step(&task, &state, &manifest),
            Err(AppWorkflowError::CorruptBinding)
        ));
    }

    #[test]
    fn immutable_material_cache_is_clone_shared_bounded_and_lock_digest_keyed() {
        let temporary = super::super::registry::tests::canonical_tempdir();
        let service = AppWorkflowService::new(ArtifactV2Workspace::new(temporary.path()));
        let cloned = service.clone();
        assert!(Arc::ptr_eq(
            &service.immutable_material_cache,
            &cloned.immutable_material_cache
        ));

        let material = immutable_material_fixture(1, b"cache-authority");
        let mut cache = AppImmutableWorkflowMaterialCache::default();
        for index in 0..=APP_IMMUTABLE_MATERIAL_CACHE_ENTRIES {
            cache
                .insert(
                    AppImmutableWorkflowMaterialKey {
                        principal: "anonymous".to_owned(),
                        workspace: "default".to_owned(),
                        package_revision_ref: format!("package-revision:{index}"),
                        package_lock_digest: format!("blake3:lock-{index}"),
                        workflow: "build".to_owned(),
                    },
                    Arc::clone(&material),
                )
                .unwrap();
        }
        assert_eq!(cache.entries.len(), APP_IMMUTABLE_MATERIAL_CACHE_ENTRIES);
        assert_eq!(cache.insertion_order.len(), cache.entries.len());
        assert!(cache.retained_bytes <= APP_IMMUTABLE_MATERIAL_CACHE_BYTES);
        assert!(!cache
            .entries
            .contains_key(&AppImmutableWorkflowMaterialKey {
                principal: "anonymous".to_owned(),
                workspace: "default".to_owned(),
                package_revision_ref: "package-revision:0".to_owned(),
                package_lock_digest: "blake3:lock-0".to_owned(),
                workflow: "build".to_owned(),
            }));

        let conflicting = immutable_material_fixture(1, b"different-authority");
        assert!(matches!(
            cache.insert(
                AppImmutableWorkflowMaterialKey {
                    principal: "anonymous".to_owned(),
                    workspace: "default".to_owned(),
                    package_revision_ref: format!(
                        "package-revision:{}",
                        APP_IMMUTABLE_MATERIAL_CACHE_ENTRIES
                    ),
                    package_lock_digest: format!(
                        "blake3:lock-{}",
                        APP_IMMUTABLE_MATERIAL_CACHE_ENTRIES
                    ),
                    workflow: "build".to_owned(),
                },
                conflicting,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));

        let before = cache.entries.len();
        let oversized = immutable_material_fixture(
            APP_IMMUTABLE_MATERIAL_CACHE_BYTES + 1,
            b"oversized-authority",
        );
        let returned = cache
            .insert(
                AppImmutableWorkflowMaterialKey {
                    principal: "anonymous".to_owned(),
                    workspace: "default".to_owned(),
                    package_revision_ref: "package-revision:oversized".to_owned(),
                    package_lock_digest: "blake3:lock-oversized".to_owned(),
                    workflow: "build".to_owned(),
                },
                Arc::clone(&oversized),
            )
            .unwrap();
        assert!(Arc::ptr_eq(&returned, &oversized));
        assert_eq!(cache.entries.len(), before);
    }

