    /// A server-owned launch authority carries no behavior binding, so
    /// `validate`'s `(None, None)` arm accepts any action id and any caller ref
    /// that is NOT behavior-shaped. These two supply exactly that, so the tests
    /// below keep asserting on what they are about -- scope, trigger, input
    /// digest and expiry -- rather than on binding identity.
    fn background_action_id() -> AppName {
        AppName::parse("scheduled_action").expect("valid action id")
    }

    fn background_caller_ref() -> AppReference {
        AppReference::parse("workflow:server-schedule").expect("valid caller ref")
    }

    #[test]
    fn background_launch_authority_is_server_owned_exact_and_short_lived() {
        use super::super::registry::tests::{authenticated_scope, reference, time};

        let authenticated = authenticated_scope("anonymous", "default");
        let installation_id = AppInstallationId::parse("install-1").unwrap();
        let mut input = fixture_task().invocation.input;
        input.source = AppDataSource::AppStore;
        input.scope_binding_ref = authenticated.scope_binding_ref().clone();
        input.source_refs = vec![source_ref(
            AppSourceRefKind::EntityRecord,
            reference("app-record:schedule-input"),
        )];
        let authority = AppBackgroundLaunchAuthority::from_server_schedule(
            &authenticated,
            installation_id.clone(),
            reference("schedule-launch:1"),
            &input,
            time(1),
        )
        .unwrap();

        authority
            .validate(
                &authenticated,
                &installation_id,
                AppManifestTrigger::Schedule,
                &background_action_id(),
                &background_caller_ref(),
                &input,
                time(2),
            )
            .unwrap();
        assert!(matches!(
            authority.validate(
                &authenticated,
                &installation_id,
                AppManifestTrigger::Event,
                &background_action_id(),
                &background_caller_ref(),
                &input,
                time(2),
            ),
            Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch)
        ));

        let mut forged = input.clone();
        forged.value = json!({"forged": true});
        assert!(matches!(
            authority.validate(
                &authenticated,
                &installation_id,
                AppManifestTrigger::Schedule,
                &background_action_id(),
                &background_caller_ref(),
                &forged,
                time(2),
            ),
            Err(AppWorkflowError::BackgroundLaunchAuthorityMismatch)
        ));
        assert!(matches!(
            authority.validate(
                &authenticated,
                &installation_id,
                AppManifestTrigger::Schedule,
                &background_action_id(),
                &background_caller_ref(),
                &input,
                time(30),
            ),
            Err(AppWorkflowError::BackgroundLaunchAuthorityExpired)
                | Err(AppWorkflowError::Authority(_))
        ));
    }

    #[test]
    fn sealed_background_input_reconstruction_preserves_source_provenance() {
        use super::super::registry::tests::reference;

        let mut task = fixture_task();
        task.trigger = AppManifestTrigger::Schedule;
        task.execution_lane = AppResourceExecutionLane::Background;
        task.invocation.input.source = AppDataSource::AppStore;
        task.invocation.input.source_refs = vec![source_ref(
            AppSourceRefKind::EntityRecord,
            reference("app-record:schedule-input"),
        )];
        task.invocation.input.content_digest =
            AppDigest::blake3(&canonical_json_bytes(&task.invocation.input.value).unwrap());
        let mut source_joined_policy = task
            .accepted_authority
            .effective_data_handling_policy
            .clone();
        source_joined_policy.classification_floor = AppDataClassification::Secret;
        source_joined_policy.model_processing = AppModelProcessing::LocalOnly;
        task.invocation.input.handling_labels.policy_digest =
            AppDigest::blake3_canonical_json(&serde_json::to_value(&source_joined_policy).unwrap())
                .unwrap();
        assert_ne!(
            task.invocation.input.handling_labels.policy_digest,
            task.accepted_authority.data_handling_policy_digest
        );
        task.input_handling_policy = Some(source_joined_policy);
        let source_refs = task.invocation.input.source_refs.clone();
        let provenance = task
            .invocation
            .input
            .handling_labels
            .provenance_digest
            .clone();
        let mut reconstructed = task.invocation.clone();

        normalize_persisted_invocation_for_execution(
            &task,
            &mut reconstructed,
            AppDataClassification::Secret,
            AppModelProcessing::LocalOnly,
        )
        .unwrap();

        assert_eq!(reconstructed.input.source, AppDataSource::AppStore);
        assert_eq!(reconstructed.input.source_refs, source_refs);
        assert_eq!(
            reconstructed.input.handling_labels.provenance_digest,
            provenance
        );
        assert_eq!(
            reconstructed.input.handling_labels.classification,
            AppDataClassification::Secret
        );

        let mut destination_only = reconstructed.clone();
        destination_only.input.handling_labels.policy_digest =
            task.accepted_authority.data_handling_policy_digest.clone();
        assert!(matches!(
            normalize_persisted_invocation_for_execution(
                &task,
                &mut destination_only,
                AppDataClassification::Secret,
                AppModelProcessing::LocalOnly,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));

        let mut forged_direct = reconstructed;
        forged_direct.input.source = AppDataSource::UserInput;
        assert!(matches!(
            normalize_persisted_invocation_for_execution(
                &task,
                &mut forged_direct,
                AppDataClassification::Sensitive,
                AppModelProcessing::LocalOnly,
            ),
            Err(AppWorkflowError::CorruptBinding)
        ));
    }

