    #[test]
    fn terminal_relation_authority_comes_from_its_unique_declared_source_entity() {
        let task = fixture_task();
        let relation = AppName::parse("parent").unwrap();
        let request = AppWorkflowTerminalRequest {
            operations: vec![AppMutationOperation::CreateRelation {
                relation: relation.clone(),
                from_record_id: super::super::models::AppRecordId::parse("record-1").unwrap(),
                to_record_id: super::super::models::AppRecordId::parse("record-2").unwrap(),
                expected_from_revision: AppRevision::new(1).unwrap(),
                expected_to_revision: AppRevision::new(1).unwrap(),
            }],
            expected_record_revisions: Vec::new(),
            output: None,
            user_visible_summary: None,
            source_artifact_refs: Vec::new(),
        };
        let allowed = BTreeMap::from([(
            relation.clone(),
            BTreeSet::from([AppName::parse("note").unwrap()]),
        )]);
        validate_terminal_request(&task, &request, &allowed)
            .expect("relation on the uniquely declared mutable source entity is allowed");

        let ambiguous = BTreeMap::from([(
            relation.clone(),
            BTreeSet::from([
                AppName::parse("note").unwrap(),
                AppName::parse("other").unwrap(),
            ]),
        )]);
        assert!(matches!(
            validate_terminal_request(&task, &request, &ambiguous),
            Err(AppWorkflowError::MutationTargetDenied(target)) if target == relation.as_str()
        ));
        assert!(matches!(
            validate_terminal_request(&task, &request, &BTreeMap::new()),
            Err(AppWorkflowError::MutationTargetDenied(target)) if target == relation.as_str()
        ));
    }

