    #[test]
    fn no_generic_action_bypasses_the_app_tool_intersection_in_v1() {
        use std::collections::HashMap;

        use crate::magician_v2::execution::capability::ImplementationType;

        let pack = |name: &str| ExecutableAction::Pack {
            capability_name: name.to_owned(),
            implementation: ImplementationType::Composite { steps: Vec::new() },
            resolved_params: HashMap::new(),
        };
        assert!(!is_structural_workflow_action(&pack("tool_search")));
        assert!(!is_structural_workflow_action(
            &ExecutableAction::SleepUntil {
                wake_at: Utc::now(),
                reason: None,
            }
        ));

        // These paths can change owner/context or project protected result
        // bytes. They stay fail-closed until their own disclosure-label and
        // runtime-guard propagation contracts exist.
        assert!(!is_structural_workflow_action(&pack("read_result")));
        assert!(!is_structural_workflow_action(
            &ExecutableAction::HandoverToAgent {
                target_agent_id: "specialist".to_owned(),
                context: "continue".to_owned(),
            }
        ));
        assert!(!is_structural_workflow_action(
            &ExecutableAction::DelegateToAgent {
                targets: Vec::new()
            }
        ));
    }

    #[test]
    fn browser_interactive_entry_accepts_only_the_four_typed_leaves() {
        use std::collections::HashMap;

        use crate::magician_v2::execution::capability::ImplementationType;

        let action = |name: &str, resolved_params| ExecutableAction::Pack {
            capability_name: name.to_owned(),
            implementation: ImplementationType::Composite { steps: Vec::new() },
            resolved_params,
        };
        assert!(matches!(
            closed_browser_action(&action(
                "browser__navigate",
                HashMap::from([
                    ("action".to_owned(), Value::String("navigate".to_owned())),
                    (
                        "url".to_owned(),
                        Value::String("https://example.test/path".to_owned()),
                    ),
                ]),
            ))
            .unwrap(),
            Some(AppBrowserAction::Navigate { .. })
        ));
        assert!(closed_browser_action(&action(
            "browser__click",
            HashMap::from([
                ("action".to_owned(), Value::String("scroll".to_owned())),
                (
                    "observation_ref".to_owned(),
                    Value::String("browser-observation:one".to_owned()),
                ),
                (
                    "element_ref".to_owned(),
                    Value::String("browser-element:one".to_owned()),
                ),
            ]),
        ))
        .is_err());
        assert!(closed_browser_action(&action(
            "browser__eval",
            HashMap::from([("script".to_owned(), Value::String("1+1".to_owned()))]),
        ))
        .unwrap()
        .is_none());
    }

