    #[test]
    fn delegated_retry_resume_and_repair_map_to_typed_resource_children() {
        let cases = [
            ("delegated_child", "delegated_child"),
            ("retry", "retry"),
            ("resume", "resume"),
            ("repair", "repair"),
        ];
        for (relationship, expected_kind) in cases {
            let admission = resource_lineage_node_admission(
                relationship,
                AppReference::parse(format!("node:{relationship}")).unwrap(),
                AppReference::parse(format!("execution:{relationship}")).unwrap(),
                AppReference::parse("node:root").unwrap(),
                7,
            )
            .unwrap();
            let encoded = serde_json::to_value(admission).unwrap();
            assert_eq!(encoded["node_kind"], expected_kind);
            assert_eq!(encoded["parent_node_id"], "node:root");
            assert_eq!(encoded["at_elapsed_ms"], 7);
        }
        assert!(matches!(
            resource_lineage_node_admission(
                "unknown",
                AppReference::parse("node:unknown").unwrap(),
                AppReference::parse("execution:unknown").unwrap(),
                AppReference::parse("node:root").unwrap(),
                0,
            ),
            Err(AppWorkflowError::InvalidExecutionLineage)
        ));
    }

    #[test]
    fn task_binding_replay_cannot_change_lane_or_procedure_narrowing() {
        let original = fixture_task();
        let mut changed_lane = original.clone();
        changed_lane.execution_lane = AppResourceExecutionLane::Background;
        assert!(!task_binding_replay_matches(&original, &changed_lane));

        let mut broadened_tools = original.clone();
        broadened_tools
            .effective_workflow_tools
            .insert(AppReference::parse("capability:http").unwrap());
        assert!(!task_binding_replay_matches(&original, &broadened_tools));

        let mut changed_personality = original.clone();
        changed_personality.resolved_personality = Some(AppName::parse("reviewer").unwrap());
        assert!(!task_binding_replay_matches(
            &original,
            &changed_personality
        ));

        let mut changed_personality_digest = original.clone();
        changed_personality_digest.resolved_personality_digest =
            Some(AppDigest::blake3(b"changed-personality"));
        assert!(!task_binding_replay_matches(
            &original,
            &changed_personality_digest
        ));

        let (receipt, _, _) = brokered_receipt_fixture();
        let mut added_transfer = original.clone();
        added_transfer.brokered_transfer_receipt = Some(receipt);
        assert!(!task_binding_replay_matches(&original, &added_transfer));
        assert!(task_binding_replay_matches(
            &added_transfer,
            &added_transfer.clone()
        ));
    }

    #[test]
    fn result_withholding_classifies_policy_loss_but_not_corruption_or_outage() {
        assert!(AppWorkflowError::StaleRuntimeAuthority.is_result_disclosure_denial());
        assert!(
            AppWorkflowError::Store(AppEntityStoreError::StaleRecordProjection)
                .is_result_disclosure_denial()
        );
        assert!(
            AppWorkflowError::Store(AppEntityStoreError::PersonalAgentPolicyDenied)
                .is_result_disclosure_denial()
        );
        assert!(!AppWorkflowError::CorruptBinding.is_result_disclosure_denial());
        assert!(
            !AppWorkflowError::Authority(AppAuthorityError::AuthenticationExpired)
                .is_result_disclosure_denial()
        );
        assert!(!AppWorkflowError::Policy(AppPolicyError::UnlabeledContent)
            .is_result_disclosure_denial());
        assert!(
            !AppWorkflowError::WorkerTerminated("worker stopped".to_owned())
                .is_result_disclosure_denial()
        );
    }

