    #[test]
    fn projection_handle_quota_is_partitioned_by_scope_and_session() {
        let now = "2026-08-21T00:00:00Z".parse::<DateTime<Utc>>().unwrap();
        let expires_at = now + chrono::Duration::minutes(10);
        let mut store = AppProjectionHandleStore::default();
        store
            .insert(
                "other-scope".to_owned(),
                projection_entry("scope_other_default", "session:other-scope", expires_at),
                now,
            )
            .unwrap();
        store
            .insert(
                "other-session".to_owned(),
                projection_entry("scope_anonymous_default", "session:other", expires_at),
                now,
            )
            .unwrap();
        for index in 0..=MAX_APP_PROJECTION_HANDLES_PER_SESSION {
            store
                .insert(
                    format!("same-session-{index}"),
                    projection_entry("scope_anonymous_default", "session:same", expires_at),
                    now,
                )
                .unwrap();
        }

        assert!(store.entries.contains_key("other-session"));
        assert!(!store.entries.contains_key("same-session-0"));
        assert_eq!(
            store.partition_entry_count(&AppProjectionHandlePartition {
                scope_binding_ref: AppScopeBindingRef::parse("scope_anonymous_default").unwrap(),
                session_ref: AppReference::parse("session:same").unwrap(),
            }),
            MAX_APP_PROJECTION_HANDLES_PER_SESSION
        );

        for index in 0..=MAX_APP_PROJECTION_HANDLES_PER_SCOPE {
            store
                .insert(
                    format!("noisy-scope-{index}"),
                    projection_entry(
                        "scope_anonymous_default",
                        format!("session:noisy-{index}").as_str(),
                        expires_at,
                    ),
                    now,
                )
                .unwrap();
        }
        assert!(store.entries.contains_key("other-scope"));
        assert!(!store.entries.contains_key("noisy-scope-0"));
        assert_eq!(
            store.scope_entry_count(&AppScopeBindingRef::parse("scope_anonymous_default").unwrap()),
            MAX_APP_PROJECTION_HANDLES_PER_SCOPE
        );
    }

    #[test]
    fn global_projection_handle_pressure_never_evicts_another_scope() {
        let now = "2026-08-21T00:00:00Z".parse::<DateTime<Utc>>().unwrap();
        let expires_at = now + chrono::Duration::minutes(10);
        let mut store = AppProjectionHandleStore::default();
        for scope_index in 0..2 {
            for entry_index in 0..MAX_APP_PROJECTION_HANDLES_PER_SCOPE {
                let scope = format!("scope_owner_{scope_index}");
                let session = format!(
                    "session:owner-{scope_index}-{}",
                    entry_index / MAX_APP_PROJECTION_HANDLES_PER_SESSION
                );
                store
                    .insert(
                        format!("owner-{scope_index}-{entry_index}"),
                        projection_entry(&scope, &session, expires_at),
                        now,
                    )
                    .unwrap();
            }
        }
        assert_eq!(store.entries.len(), MAX_APP_PROJECTION_HANDLES);

        let error = store
            .insert(
                "third-scope".to_owned(),
                projection_entry("scope_third", "session:third", expires_at),
                now,
            )
            .unwrap_err();

        assert!(matches!(
            error,
            AppWorkflowError::ProjectionHandleStoreOverflow
        ));
        assert_eq!(store.entries.len(), MAX_APP_PROJECTION_HANDLES);
        assert!(store.entries.contains_key("owner-0-0"));
        assert!(store.entries.contains_key("owner-1-0"));
        assert!(!store.entries.contains_key("third-scope"));
    }

