    #[tokio::test]
    async fn workflow_sidecar_seal_rejects_payload_tamper_and_cross_scope_copy() {
        let temp = tempfile::tempdir().unwrap();
        let workspace = ArtifactV2Workspace::new(temp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let copied_scope = ScopeRef::system_internal_unauthenticated(
            &"another-owner".to_owned(),
            &"default".to_owned(),
        );
        let path = temp.path().join("sealed-binding.json");
        let task = fixture_task();

        write_sealed_sidecar(
            &workspace,
            &scope,
            "task-binding",
            &task.task_id,
            None,
            &path,
            &task,
        )
        .await
        .unwrap();
        let original_bytes = std::fs::read(&path).unwrap();
        let loaded = read_optional_sealed_sidecar::<AppWorkflowTaskBinding>(
            &workspace,
            &scope,
            "task-binding",
            &task.task_id,
            None,
            &path,
            MAX_TASK_BINDING_BYTES,
        )
        .await
        .unwrap()
        .unwrap();
        assert!(task_binding_replay_matches(&loaded, &task));

        // A registry publisher can encode a Value instead of the Rust struct.
        // That changes key order and whitespace, but preserves the sealed data.
        let published: Value = serde_json::from_slice(&original_bytes).unwrap();
        let published_bytes = serde_json::to_vec(&published).unwrap();
        assert_ne!(published_bytes, original_bytes);
        assert!(sealed_control_json_matches(&published_bytes, &original_bytes).unwrap());
        std::fs::write(&path, &published_bytes).unwrap();
        let reopened = read_optional_sealed_sidecar::<AppWorkflowTaskBinding>(
            &workspace,
            &scope,
            "task-binding",
            &task.task_id,
            None,
            &path,
            MAX_TASK_BINDING_BYTES,
        )
        .await
        .unwrap()
        .unwrap();
        let resealed = sealed_sidecar_bytes(
            &workspace,
            &scope,
            "task-binding",
            &task.task_id,
            None,
            &reopened,
        )
        .unwrap();
        assert!(sealed_control_json_matches(&published_bytes, &resealed).unwrap());
        let mut wrong_seal = published.clone();
        wrong_seal["hmac_sha256"] = json!("invalid");
        assert!(
            !sealed_control_json_matches(&serde_json::to_vec(&wrong_seal).unwrap(), &resealed,)
                .unwrap()
        );

        let mut forged: Value = serde_json::from_slice(&original_bytes).unwrap();
        forged["payload"]["invocation"]["input"]["value"] = json!({"secret": "forged-body"});
        std::fs::write(&path, serde_json::to_vec(&forged).unwrap()).unwrap();
        assert!(matches!(
            read_optional_sealed_sidecar::<AppWorkflowTaskBinding>(
                &workspace,
                &scope,
                "task-binding",
                &task.task_id,
                None,
                &path,
                MAX_TASK_BINDING_BYTES,
            )
            .await,
            Err(AppWorkflowError::CorruptBinding)
        ));

        std::fs::write(&path, original_bytes).unwrap();
        assert!(matches!(
            read_optional_sealed_sidecar::<AppWorkflowTaskBinding>(
                &workspace,
                &copied_scope,
                "task-binding",
                &task.task_id,
                None,
                &path,
                MAX_TASK_BINDING_BYTES,
            )
            .await,
            Err(AppWorkflowError::CorruptBinding)
        ));
    }

    #[test]
    fn workflow_sidecar_seal_bounded_snapshot_keeps_encoded_and_identity_limits() {
        let temp = tempfile::tempdir().unwrap();
        let workspace = ArtifactV2Workspace::new(temp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let task_id = "task_sealed_snapshot";
        let execution_id = "exec_sealed_snapshot";
        let payload = json!({"records": [{"body": "bounded retained context"}]});
        let bytes = sealed_sidecar_bytes(
            &workspace,
            &scope,
            "run-state",
            task_id,
            Some(execution_id),
            &payload,
        )
        .unwrap();
        let decode = |candidate: &[u8], limit, execution| {
            open_sealed_control_blob_bounded::<Box<Value>>(
                &workspace,
                &scope,
                "run-state",
                task_id,
                Some(execution),
                candidate,
                limit,
            )
        };
        assert_eq!(
            *decode(&bytes, MAX_RUN_STATE_BYTES, execution_id).unwrap(),
            payload
        );
        let mut published: Value = serde_json::from_slice(&bytes).unwrap();
        let reordered = serde_json::to_vec(&published).unwrap();
        assert_eq!(
            *decode(&reordered, MAX_RUN_STATE_BYTES, execution_id).unwrap(),
            payload
        );
        assert!(decode(&bytes, bytes.len() as u64 - 1, execution_id).is_err());
        assert!(decode(&bytes, MAX_RUN_STATE_BYTES, "exec_another").is_err());
        published["payload"]["records"][0]["body"] = json!("forged context");
        assert!(decode(
            &serde_json::to_vec(&published).unwrap(),
            MAX_RUN_STATE_BYTES,
            execution_id
        )
        .is_err());
        let mut trailing = bytes.clone();
        trailing.extend_from_slice(b" null");
        assert!(decode(&trailing, MAX_RUN_STATE_BYTES, execution_id).is_err());
        let deep = format!(
            "{}0{}",
            "[".repeat(MAX_JSON_DEPTH + 1),
            "]".repeat(MAX_JSON_DEPTH + 1)
        );
        assert!(decode(deep.as_bytes(), MAX_RUN_STATE_BYTES, execution_id).is_err());
        let wide = format!("[{}0]", "0,".repeat(MAX_JSON_NODES));
        assert!(decode(wide.as_bytes(), MAX_RUN_STATE_BYTES, execution_id).is_err());
    }

    #[test]
    fn workflow_run_state_reopens_legacy_pretty_snapshot_and_bounds_new_publication() {
        let temp = tempfile::tempdir().unwrap();
        let workspace = ArtifactV2Workspace::new(temp.path());
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let row = json!({"fields": {"body": "a".repeat(220), "id": "participant"},
            "checkpoint": {"digest": "b".repeat(64), "kind": "query"}});
        let payload = json!({"queries": vec![row; 4500]});
        let encoded = sealed_sidecar_bytes(
            &workspace,
            &scope,
            "run-state",
            "task_legacy_pretty",
            Some("exec_legacy_pretty"),
            &payload,
        )
        .unwrap();
        assert!(encoded.len() as u64 <= MAX_RUN_STATE_BYTES);
        let mut envelope: Value = serde_json::from_slice(&encoded).unwrap();
        let legacy = serde_json::to_vec_pretty(&envelope).unwrap();
        assert!(legacy.len() as u64 > MAX_RUN_STATE_BYTES);
        let open = |bytes: &[u8]| {
            open_sealed_control_blob_bounded::<Value>(
                &workspace,
                &scope,
                "run-state",
                "task_legacy_pretty",
                Some("exec_legacy_pretty"),
                bytes,
                MAX_RUN_STATE_BYTES,
            )
        };
        assert_eq!(open(&legacy).unwrap(), payload);
        envelope["payload"]["queries"][0]["fields"]["body"] = json!("forged");
        assert!(open(&serde_json::to_vec_pretty(&envelope).unwrap()).is_err());
        assert!(matches!(
            sealed_sidecar_bytes(
                &workspace,
                &scope,
                "run-state",
                "task_legacy_pretty",
                Some("exec_legacy_pretty"),
                &json!({"body": "x".repeat(MAX_RUN_STATE_BYTES as usize)})
            ),
            Err(AppWorkflowError::ToolResultTooLarge)
        ));
    }

