    #[test]
    fn remaining_physical_window_never_restarts_the_absolute_deadline() {
        let admitted_at = tokio::time::Instant::now();
        let deadline = admitted_at + std::time::Duration::from_secs(10);
        assert_eq!(
            remaining_physical_resource_window(
                deadline,
                admitted_at + std::time::Duration::from_secs(4),
            ),
            std::time::Duration::from_secs(6)
        );
        assert!(remaining_physical_resource_window(deadline, deadline).is_zero());
        assert!(remaining_physical_resource_window(
            deadline,
            deadline + std::time::Duration::from_secs(1),
        )
        .is_zero());
    }

    #[test]
    fn provider_deadline_tracks_physical_timeout_and_never_crosses_run_lifetime() {
        assert_eq!(
            bounded_operation_deadline(10_000, 300, 600, 600, 0).unwrap(),
            310_000
        );
        assert!(matches!(
            bounded_operation_deadline(590_000, 300, 600, 600, 0),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
        assert!(matches!(
            bounded_operation_deadline(10_000, 300, 600, 60, 55_000),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
        assert!(matches!(
            bounded_operation_deadline(600_000, 1, 600, 600, 0),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
        assert!(matches!(
            bounded_operation_deadline(1, 0, 600, 600, 0),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
        assert!(matches!(
            bounded_operation_deadline(1, MAX_APP_OPERATION_TIMEOUT_SECS + 1, 1_000, 1_000, 0,),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
        assert!(matches!(
            bounded_operation_deadline(1, 1, 600, 60, 60_000),
            Err(AppWorkflowError::OperationDeadlineUnavailable)
        ));
    }

    #[test]
    fn oversized_governed_mcp_success_projects_a_non_retry_stub() {
        let oversized =
            ActionResult::text("x".repeat(MAX_APP_GOVERNED_MCP_RESULT_BYTES as usize + 8));
        let (projected, bytes) = project_governed_mcp_success_result(
            oversized,
            MAX_APP_GOVERNED_MCP_RESULT_BYTES as usize,
        );
        assert!(!bytes.is_empty());
        assert!(bytes.len() <= MAX_APP_GOVERNED_MCP_RESULT_BYTES as usize);
        let ActionResult::Text { content } = projected else {
            panic!("truncated MCP success must remain text");
        };
        assert!(content.contains("do not retry"));
        assert!(content.contains("truncated"));

        let oversized =
            ActionResult::text("x".repeat(MAX_APP_GOVERNED_MCP_RESULT_BYTES as usize + 8));
        let (projected, bytes) = project_governed_mcp_success_result(oversized, 0);
        assert!(!bytes.is_empty());
        let ActionResult::Text { content } = projected else {
            panic!("zero-ceiling MCP success must still project the non-retry stub");
        };
        assert!(content.contains("do not retry"));
    }

