    fn fixture_labeled_result(
        execution_ref: &str,
        invocation_ref: &str,
        value: Value,
    ) -> AppLabeledToolResultRecord {
        let bytes = canonical_json_bytes(&value).unwrap();
        let handling_labels = AppHandlingLabels {
            classification: AppDataClassification::Secret,
            model_processing: AppModelProcessing::LocalOnly,
            policy_digest: AppDigest::blake3(b"result-policy"),
            provenance_digest: AppDigest::blake3(b"result-provenance"),
        };
        let handling_digest = AppDigest::blake3(
            &canonical_json_bytes(&serde_json::to_value(&handling_labels).unwrap()).unwrap(),
        );
        serde_json::from_value(json!({
            "checkpoint": {
                "protocol_version": "1",
                "execution_ref": execution_ref,
                "invocation_ref": invocation_ref,
                "tool_ref": "capability:fixture",
                "transport_digest": AppDigest::blake3(b"transport"),
                "disclosure_digest": AppDigest::blake3(b"disclosure"),
                "disclosure_byte_count": 1,
                "authority_digest": AppDigest::blake3(b"authority"),
                "content_digest": AppDigest::blake3(&bytes),
                "byte_count": bytes.len(),
                "handling_digest": handling_digest
            },
            "handling_labels": handling_labels,
            "value": value
        }))
        .unwrap()
    }

    #[test]
    fn os_jail_audit_sidecar_rejects_receipt_digest_tampering() {
        let task = fixture_task();
        let execution_id = "exec_audit_1";
        let mut state = fixture_run_state(&task, execution_id, "personal-assistant");
        let invocation_ref = AppReference::parse("tool-invocation:audit-1").unwrap();
        let effect_binding_digest = AppDigest::blake3(b"effect-binding");
        let audit_value = json!({
            "schema_version": "fixture.audit.v1",
            "terminal": {"dispatch": "dispatched"}
        });
        let audit_bytes = canonical_json_bytes(&audit_value).unwrap();
        let audit_digest = AppDigest::blake3(&audit_bytes);
        let result = ActionResult::Browser {
            data: json!({
                "kind": "app_os_jail",
                "success": true,
                "audit_digest": audit_digest.as_str(),
            }),
        };
        let result_bytes =
            canonical_effect_result_bytes(&result, MAX_APP_ACTION_RESULT_BYTES).unwrap();
        let receipt = AppEffectSettlementReceipt::committed_result(
            effect_binding_digest.clone(),
            &result_bytes,
        )
        .unwrap();
        let result_digest = receipt.result().unwrap().result_digest.clone();
        state
            .effect_completion_intents
            .push(AppEffectCompletionIntent {
                schema: APP_EFFECT_COMPLETION_INTENT_SCHEMA.to_owned(),
                task_id: task.task_id.clone(),
                execution_id: AppReference::parse(execution_id).unwrap(),
                invocation_ref: invocation_ref.clone(),
                effect_binding_schema: APP_EFFECT_BINDING_SCHEMA_V2.to_owned(),
                effect_binding_digest: effect_binding_digest.clone(),
                canonical_input_digest: AppDigest::blake3(b"{}"),
                result_byte_ceiling: MAX_APP_ACTION_RESULT_BYTES as u64,
                dispatch_started_at_elapsed_ms: 1,
                provider_completed_at_elapsed_ms: 2,
                canonical_result_base64: URL_SAFE_NO_PAD.encode(&result_bytes),
                receipt,
                consumed_checkpoint_digest: None,
            });
        state.os_jail_audit_records.push(AppOsJailAuditRecord {
            schema: APP_OS_JAIL_AUDIT_RECORD_SCHEMA.to_owned(),
            task_id: task.task_id.clone(),
            execution_id: AppReference::parse(execution_id).unwrap(),
            invocation_ref,
            effect_binding_digest,
            disposition: AppEffectSettlementDisposition::CommitObserved,
            dispatch: "dispatched".to_owned(),
            receipt_digest: Some(audit_digest),
            canonical_receipt_base64: Some(URL_SAFE_NO_PAD.encode(&audit_bytes)),
            result_digest: Some(result_digest),
        });

        assert!(validate_effect_completion_intents(&state, &task.task_id, execution_id).is_ok());
        let mut legacy = state.clone();
        legacy.effect_completion_intents[0].schema =
            "magician.app-effect-completion-intent.v1".to_owned();
        legacy.effect_completion_intents[0].effect_binding_schema =
            APP_EFFECT_BINDING_SCHEMA_V1.to_owned();
        assert!(matches!(
            validate_effect_completion_intents(&legacy, &task.task_id, execution_id),
            Err(AppWorkflowError::LegacyEffectBindingReconciliationRequired)
        ));
        state.os_jail_audit_records[0].receipt_digest = Some(AppDigest::blake3(b"tampered"));
        assert!(matches!(
            validate_effect_completion_intents(&state, &task.task_id, execution_id),
            Err(AppWorkflowError::EffectCompletionIntentCorrupt)
        ));
    }

    #[test]
    fn completion_retains_small_results_under_a_larger_reviewed_transport_ceiling() {
        let transport_ceiling = 512 * 1024;
        let result = ActionResult::text("bounded host-read result");
        let bytes = canonical_effect_result_bytes(&result, transport_ceiling).unwrap();
        let effect_digest = AppDigest::blake3(b"reviewed-host-read");
        let mut intent = AppEffectCompletionIntent {
            schema: APP_EFFECT_COMPLETION_INTENT_SCHEMA.to_owned(),
            task_id: "task_host_read".to_owned(),
            execution_id: AppReference::parse("exec_host_read").unwrap(),
            invocation_ref: AppReference::parse("tool-invocation:host-read").unwrap(),
            effect_binding_schema: APP_EFFECT_BINDING_SCHEMA_V2.to_owned(),
            effect_binding_digest: effect_digest.clone(),
            canonical_input_digest: AppDigest::blake3(b"{}"),
            result_byte_ceiling: transport_ceiling as u64,
            dispatch_started_at_elapsed_ms: 1,
            provider_completed_at_elapsed_ms: 2,
            canonical_result_base64: URL_SAFE_NO_PAD.encode(&bytes),
            receipt: AppEffectSettlementReceipt::committed_result(effect_digest, &bytes).unwrap(),
            consumed_checkpoint_digest: None,
        };
        assert_eq!(decode_effect_completion_result(&intent).unwrap().1, bytes);
        let oversized = ActionResult::text("x".repeat(MAX_APP_ACTION_RESULT_BYTES));
        assert!(canonical_effect_result_bytes(&oversized, transport_ceiling).is_err());
        // A larger transport allowance must never widen durable retention.
        intent.canonical_result_base64 =
            URL_SAFE_NO_PAD.encode(vec![b'x'; MAX_APP_ACTION_RESULT_BYTES + 1]);
        assert!(decode_effect_completion_result(&intent).is_err());
    }

