    #[test]
    fn prebinding_recovery_accepts_only_the_pristine_pending_app_shell() {
        let task_id = format!("task_app_{}", "a".repeat(64));
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let installation_id = AppInstallationId::parse("install-1").unwrap();
        let mut task = pristine_prebinding_task_fixture(&task_id, &scope, &installation_id);

        // This is the lifecycle written by the production App task owner.
        task.manifest.lifecycle = TaskLifecycle::Internal;

        assert!(exact_prebinding_app_task_is_recoverable(
            &task,
            &scope,
            &task_id,
            &installation_id,
        ));
        task.state.status = "ready".to_owned();
        assert!(!exact_prebinding_app_task_is_recoverable(
            &task,
            &scope,
            &task_id,
            &installation_id,
        ));
        task.state.status = "pending".to_owned();
        task.state.latest_root_execution_id = Some("exec_prior".to_owned());
        assert!(!exact_prebinding_app_task_is_recoverable(
            &task,
            &scope,
            &task_id,
            &installation_id,
        ));
    }

    #[test]
    fn prebinding_recovery_preserves_legacy_shells_and_rejects_foreign_identity() {
        let task_id = format!("task_app_{}", "b".repeat(64));
        let scope = ScopeRef::system_internal_unauthenticated(
            &"anonymous".to_owned(),
            &"default".to_owned(),
        );
        let installation_id = AppInstallationId::parse("install-1").unwrap();
        let mut task = pristine_prebinding_task_fixture(&task_id, &scope, &installation_id);
        assert!(exact_prebinding_app_task_is_recoverable(
            &task,
            &scope,
            &task_id,
            &installation_id,
        ));
        for lifecycle in [TaskLifecycle::Internal, TaskLifecycle::Persistent] {
            task.manifest.lifecycle = lifecycle;
            task.manifest.created_by = "user".to_owned();
            assert!(!exact_prebinding_app_task_is_recoverable(
                &task,
                &scope,
                &task_id,
                &installation_id,
            ));
            task.manifest.created_by = "app_action".to_owned();
            task.manifest.workspace = "another_workspace".to_owned();
            assert!(!exact_prebinding_app_task_is_recoverable(
                &task,
                &scope,
                &task_id,
                &installation_id,
            ));
            task.manifest.workspace = "default".to_owned();
        }
    }

