    #[test]
    fn effect_only_brokered_result_inherits_the_accepted_transfer_policy() {
        let (receipt, _, _) = brokered_receipt_fixture();
        let transfer_policy = brokered_policy_fixture();
        let mut task = fixture_task();
        task.brokered_transfer_receipt = Some(receipt);
        task.brokered_transfer_policy = Some(transfer_policy.clone());
        task.accepted_authority.effective_data_handling_policy = transfer_policy.clone();
        let result = AppActionResult {
            protocol_version: AppProtocolVersion::V1,
            action_id: task.invocation.action_id.clone(),
            run_ref: AppReference::parse("run:app-action:task_app_fixture").unwrap(),
            status: AppActionStatus::Completed,
            output: None,
            mutation_receipt_refs: vec![AppReference::parse("mutation:effect-only").unwrap()],
            external_effect_receipt_refs: Vec::new(),
            error: None,
        };

        assert_eq!(
            workflow_result_policy(&task, &result).unwrap(),
            transfer_policy
        );
        let audience = AppStoreReadAudience::PersonalAgent {
            execution_ref: AppReference::parse("execution:personal-agent").unwrap(),
            processing_class: super::super::boundary::AppAgentProcessingClass::LocalModel,
            maximum_classification: AppDataClassification::Secret,
        };
        let (projected, withheld, policy) =
            personal_agent_result_projection(&task, result, &audience).unwrap();
        assert!(!withheld);
        assert!(policy.is_some());
        assert!(projected.is_some_and(|result| result.effect_committed));
    }

